public static void extractZipFileWithPermissions(String zipFilePath, String targetPath)
            throws IOException {
        try (ZipFile zipFile = new ZipFile(zipFilePath)) {
            Enumeration<ZipArchiveEntry> entries = zipFile.getEntries();
            boolean isUnix = isUnix();
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            String canonicalTargetPath = new File(targetPath).getCanonicalPath() + File.separator;

            while (entries.hasMoreElements()) {
                ZipArchiveEntry entry = entries.nextElement();
                File outputFile = new File(canonicalTargetPath, entry.getName());
                if (!outputFile.getCanonicalPath().startsWith(canonicalTargetPath)) {
                    throw new IOException(
                            "Expand "
                                    + entry.getName()
                                    + " would create a file outside of "
                                    + targetPath);
                }

                if (entry.isDirectory()) {
                    if (!outputFile.exists()) {
                        if (!outputFile.mkdirs()) {
                            throw new IOException(
                                    "Create dir: " + outputFile.getAbsolutePath() + " failed!");
                        }
                    }
                } else {
                    File parentDir = outputFile.getParentFile();
                    if (!parentDir.exists()) {
                        if (!parentDir.mkdirs()) {
                            throw new IOException(
                                    "Create dir: " + outputFile.getAbsolutePath() + " failed!");
                        }
                    }
                    if (entry.isUnixSymlink()) {
                        // the content of the file is the target path of the symlink
                        baos.reset();
                        IOUtils.copyBytes(zipFile.getInputStream(entry), baos);
                        Files.createSymbolicLink(
                                outputFile.toPath(), new File(parentDir, baos.toString()).toPath());
                    } else if (outputFile.createNewFile()) {
                        OutputStream output = new FileOutputStream(outputFile);
                        IOUtils.copyBytes(zipFile.getInputStream(entry), output);
                    } else {
                        throw new IOException(
                                "Create file: " + outputFile.getAbsolutePath() + " failed!");
                    }
                }
                if (isUnix) {
                    int mode = entry.getUnixMode();
                    if (mode != 0) {
                        Path outputPath = Paths.get(outputFile.toURI());
                        Set<PosixFilePermission> permissions = new HashSet<>();
                        addIfBitSet(mode, 8, permissions, PosixFilePermission.OWNER_READ);
                        addIfBitSet(mode, 7, permissions, PosixFilePermission.OWNER_WRITE);
                        addIfBitSet(mode, 6, permissions, PosixFilePermission.OWNER_EXECUTE);
                        addIfBitSet(mode, 5, permissions, PosixFilePermission.GROUP_READ);
                        addIfBitSet(mode, 4, permissions, PosixFilePermission.GROUP_WRITE);
                        addIfBitSet(mode, 3, permissions, PosixFilePermission.GROUP_EXECUTE);
                        addIfBitSet(mode, 2, permissions, PosixFilePermission.OTHERS_READ);
                        addIfBitSet(mode, 1, permissions, PosixFilePermission.OTHERS_WRITE);
                        addIfBitSet(mode, 0, permissions, PosixFilePermission.OTHERS_EXECUTE);
                        // the permission of the target file will be set to be the same as the
                        // symlink
                        // TODO: support setting the permission without following links
                        try {
                            Files.setPosixFilePermissions(outputPath, permissions);
                        } catch (NoSuchFileException e) {
                            // this may happens when the target file of the symlink is still not
                            // extracted
                        }
                    }
                }
            }
        }
    }

public static Duration parseDuration(String text) {
        checkNotNull(text);

        final String trimmed = text.trim();
        checkArgument(!trimmed.isEmpty(), "argument is an empty- or whitespace-only string");

        final int len = trimmed.length();
        int pos = 0;

        char current;
        while (pos < len && (current = trimmed.charAt(pos)) >= '0' && current <= '9') {
            pos++;
        }

        final String number = trimmed.substring(0, pos);
        final String unitLabel = trimmed.substring(pos).trim().toLowerCase(Locale.US);

        if (number.isEmpty()) {
            try {
                // Fall back to parse ISO-8601 duration format
                Duration parsedDuration = Duration.parse(trimmed);
                if (parsedDuration.isNegative()) {
                    // Don't support negative duration which is consistent with before format
                    throw new NumberFormatException("negative duration is not supported");
                }
                return parsedDuration;
            } catch (DateTimeParseException e) {
                throw new NumberFormatException(
                        "text does not start with a number, and is not a valid ISO-8601 duration format: "
                                + trimmed);
            }
        }

        final BigInteger value;
        try {
            value = new BigInteger(number); // this throws a NumberFormatException
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                    "The value '" + number + "' cannot be represented as an integer number.", e);
        }

        final ChronoUnit unit;
        if (unitLabel.isEmpty()) {
            unit = ChronoUnit.MILLIS;
        } else {
            unit = LABEL_TO_UNIT_MAP.get(unitLabel);
        }
        if (unit == null) {
            throw new IllegalArgumentException(
                    "Time interval unit label '"
                            + unitLabel
                            + "' does not match any of the recognized units: "
                            + TimeUnit.getAllUnits());
        }

        try {
            return convertBigIntToDuration(value, unit);
        } catch (ArithmeticException e) {
            throw new IllegalArgumentException(
                    "The value '"
                            + number
                            + "' cannot be represented as Duration (numeric overflow).",
                    e);
        }
    }

public static void main(String[] args) throws IOException {
        if (args.length != 2) {
            System.out.println(
                    "Exactly 2 paths must be provided, the expected result path and the actual result path");
            System.exit(1);
        }

        String expectedPath = args[0];
        String actualPath = args[1];

        File[] partitions = new File(actualPath).listFiles();
        if (partitions == null) {
            throw new IllegalArgumentException(
                    String.format(
                            "The specified actual result path: %s doesn't exists.", actualPath));
        }
        if (partitions.length > 1) {
            throw new UnsupportedOperationException(
                    "Please set the sink.parallelism 1 to keep the partition number is 1.");
        }

        try (BufferedReader expectedReader = new BufferedReader(new FileReader(expectedPath));
                BufferedReader actualReader = new BufferedReader(new FileReader(partitions[0]))) {
            int expectedLineNum = 0;
            int actualLineNum = 0;

            String expectedLine, actualLine;
            while ((expectedLine = expectedReader.readLine()) != null
                    && (actualLine = actualReader.readLine()) != null) {
                String[] expected = expectedLine.split("\\|");
                expectedLineNum++;
                String[] actual = actualLine.split("\\|");
                actualLineNum++;

                if (expected.length != actual.length) {
                    System.out.println(
                            "Incorrect number of columns on line "
                                    + actualLineNum
                                    + "! Expecting "
                                    + expected.length
                                    + " columns, but found "
                                    + actual.length
                                    + " columns.");
                    System.exit(1);
                }
                for (int i = 0; i < expected.length; i++) {
                    boolean failed;
                    try {
                        long e = Long.valueOf(expected[i]);
                        long a = Long.valueOf(actual[i]);
                        failed = (e != a);
                    } catch (NumberFormatException nfe) {
                        try {
                            double e = Double.valueOf(expected[i]);
                            double a = Double.valueOf(actual[i]);
                            if (e < 0 && a > 0 || e > 0 && a < 0) {
                                failed = true;
                            } else {
                                if (e < 0) {
                                    e = -e;
                                    a = -a;
                                }
                                double t = round(a, 2);
                                // defined in TPC-H standard specification v2.18.0 section 2.1.3.5
                                failed = (e * 0.99 > t || e * 1.01 < t);
                            }
                        } catch (NumberFormatException nfe2) {
                            failed =
                                    !expected[i]
                                            .trim()
                                            .equals(actual[i].replaceAll("\"", "").trim());
                        }
                    }
                    if (failed) {
                        System.out.println(
                                "Incorrect result on line "
                                        + actualLineNum
                                        + " column "
                                        + (i + 1)
                                        + "! Expecting "
                                        + expected[i]
                                        + ", but found "
                                        + actual[i]
                                        + ".");
                        System.exit(1);
                    }
                }
            }

            while (expectedReader.readLine() != null) {
                expectedLineNum++;
            }
            while (actualReader.readLine() != null) {
                actualLineNum++;
            }
            if (expectedLineNum != actualLineNum) {
                System.out.println(
                        "Incorrect number of lines! Expecting "
                                + expectedLineNum
                                + " lines, but found "
                                + actualLineNum
                                + " lines.");
                System.exit(1);
            }
        }
