@Nullable
    public static Object toInternal(@Nullable Object value, LogicalType type) {
        if (value == null) {
            return null;
        }

        switch (type.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                if (value instanceof StringData) {
                    return value;
                }
                return StringData.fromString(value.toString());

            case BOOLEAN:
            case TINYINT:
            case SMALLINT:
            case INTEGER:
            case BIGINT:
            case FLOAT:
            case DOUBLE:
            case TIME_WITHOUT_TIME_ZONE:
            case INTERVAL_YEAR_MONTH:
            case INTERVAL_DAY_TIME:
                return value;

            case DECIMAL:
                if (value instanceof DecimalData) {
                    return value;
                }
                if (value instanceof BigDecimal) {
                    DecimalType dt = (DecimalType) type;
                    return DecimalData.fromBigDecimal(
                            (BigDecimal) value, dt.getPrecision(), dt.getScale());
                }
                if (value instanceof ByteBuffer) {
                    DecimalType dt = (DecimalType) type;
                    return DecimalData.fromUnscaledBytes(
                            toByteArray((ByteBuffer) value), dt.getPrecision(), dt.getScale());
                }
                if (value instanceof byte[]) {
                    DecimalType dt = (DecimalType) type;
                    return DecimalData.fromUnscaledBytes(
                            (byte[]) value, dt.getPrecision(), dt.getScale());
                }
                return value;

            case DATE:
                if (value instanceof Integer) {
                    return value;
                }
                if (value instanceof java.sql.Date) {
                    return (int) ((java.sql.Date) value).toLocalDate().toEpochDay();
                }
                if (value instanceof LocalDate) {
                    return (int) ((LocalDate) value).toEpochDay();
                }
                return value;

            case TIMESTAMP_WITHOUT_TIME_ZONE:
            case TIMESTAMP_WITH_TIME_ZONE:
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                if (value instanceof TimestampData) {
                    return value;
                }
                if (value instanceof Timestamp) {
                    return TimestampData.fromTimestamp((Timestamp) value);
                }
                if (value instanceof Instant) {
                    return TimestampData.fromInstant((Instant) value);
                }
                if (value instanceof LocalDateTime) {
                    return TimestampData.fromLocalDateTime((LocalDateTime) value);
                }
                return value;

            case BINARY:
            case VARBINARY:
                if (value instanceof ByteBuffer) {
                    return toByteArray((ByteBuffer) value);
                }
                return value;

            case NULL:
                return null;

            case ROW:
            case STRUCTURED_TYPE:
                if (value instanceof GenericRowData) {
                    return value;
                }
                if (value instanceof Row) {
                    return rowToGenericRowData((Row) value, (RowType) type);
                }
                return value;

            case ARRAY:
                if (value instanceof GenericArrayData) {
                    return value;
                }
                ArrayType at = (ArrayType) type;
                if (value instanceof Object[]) {
                    return objectArrayToArrayData((Object[]) value, at.getElementType());
                }
                if (value instanceof Iterable) {
                    return iterableToArrayData((Iterable<?>) value, at.getElementType());
                }
                return value;

            case MAP:
                if (value instanceof GenericMapData) {
                    return value;
                }
                MapType mt = (MapType) type;
                if (value instanceof Map) {
                    return mapToMapData((Map<?, ?>) value, mt.getKeyType(), mt.getValueType());
                }
                if (value instanceof Iterable) {
                    return mapEntryIterableToMapData(
                            (Iterable<?>) value, mt.getKeyType(), mt.getValueType());
                }
                return value;

            case MULTISET:
                // MultisetType is not a MapType: it has only an element type, represented
                // internally as Map<element, Integer> (element -> multiplicity).
                if (value instanceof GenericMapData) {
                    return value;
                }
                LogicalType elementType = ((MultisetType) type).getElementType();
                if (value instanceof Map) {
                    return mapToMapData((Map<?, ?>) value, elementType, new IntType());
                }
                if (value instanceof Iterable) {
                    return mapEntryIterableToMapData(
                            (Iterable<?>) value, elementType, new IntType());
                }
                return value;

            default:
                throw new UnsupportedOperationException(
                        "Cannot convert value of type '"
                                + value.getClass().getName()
                                + "' to internal representation for LogicalTypeRoot "
                                + type.getTypeRoot()
                                + ".");
        }
    }

@Override
    public CatalogBaseTable getTable(ObjectPath tablePath)
            throws TableNotExistException, CatalogException {
        Optional<String> snapshotPath = discovery.find(tablePath.getDatabaseName());
        if (snapshotPath.isEmpty()) {
            throw new TableNotExistException(getName(), tablePath);
        }
        String tableName = tablePath.getObjectName();
        if (METADATA_TABLE.equals(tableName)) {
            return buildMetadataView(snapshotPath.get());
        }
        try {
            CheckpointMetadata metadata = SavepointLoader.loadSavepointMetadata(snapshotPath.get());
            ResolvedTable resolved =
                    resolveTable(metadata, tableName)
                            .orElseThrow(() -> new TableNotExistException(getName(), tablePath));
            switch (resolved.kind) {
                case KEYED:
                    {
                        KeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getStateCatalogTable(
                                metadata,
                                schemaInfo,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                case KEYED_FLAT:
                    {
                        KeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getFlattenedStateCatalogTable(
                                metadata,
                                schemaInfo,
                                resolved.stateName,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                case WINDOWED:
                    {
                        KeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getWindowKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getWindowStateCatalogTable(
                                metadata,
                                schemaInfo,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                case WINDOWED_FLAT:
                    {
                        KeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getWindowKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getFlattenedWindowStateCatalogTable(
                                metadata,
                                schemaInfo,
                                resolved.stateName,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                case LIST:
                case UNION:
                    {
                        NonKeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getNonKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getOperatorStateCatalogTable(
                                schemaInfo,
                                resolved.stateName,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                case BROADCAST:
                    {
                        NonKeyedStateSchemaInfo schemaInfo =
                                StateTableUtils.getNonKeyedStateSchema(
                                        metadata, resolved.operatorIdentifier);
                        return StateTableUtils.getBroadcastStateCatalogTable(
                                schemaInfo,
                                resolved.stateName,
                                snapshotPath.get(),
                                resolved.operatorIdentifier);
                    }
                default:
                    throw new IllegalStateException("Unhandled table kind " + resolved.kind);
            }
        } catch (IOException e) {
            throw new CatalogException(
                    "Failed to load state schema for table '" + tablePath + "'", e);
        }
    }

