            JobType jobType,
            Iterable<JobVertex> vertices,
            VertexParallelism vertexParallelism) {
        try {
            Collection<JobPlanInfo.Plan.Node> nodes = new ArrayList<>();

            // info per vertex
            for (JobVertex vertex : vertices) {

                String operator =
                        vertex.getOperatorName() != null ? vertex.getOperatorName() : NOT_SET;

                String operatorDescr =
                        vertex.getOperatorDescription() != null
                                ? vertex.getOperatorDescription()
                                : NOT_SET;

                String optimizerProps =
                        vertex.getResultOptimizerProperties() != null
                                ? vertex.getResultOptimizerProperties()
                                : EMPTY;

                String description =
                        vertex.getOperatorPrettyName() != null
                                ? vertex.getOperatorPrettyName()
                                : vertex.getName();

                // make sure the encoding is HTML pretty
                description = StringEscapeUtils.escapeHtml4(description);
                description = description.replace("\n", "<br/>");
                description = description.replace("\\", "&#92;");

                operatorDescr = StringEscapeUtils.escapeHtml4(operatorDescr);
                operatorDescr = operatorDescr.replace("\n", "<br/>");

                JobVertexID vertexID = vertex.getID();
                long parallelism =
                        vertexParallelism
                                .getParallelismOptional(vertexID)
                                .orElse(vertex.getParallelism());
                Collection<JobPlanInfo.Plan.Node.Input> inputs = new ArrayList<>();

                if (!vertex.isInputVertex()) {
                    for (int inputNum = 0; inputNum < vertex.getInputs().size(); inputNum++) {
                        JobEdge edge = vertex.getInputs().get(inputNum);
                        if (edge.getSource() == null) {
                            continue;
                        }
                        JobVertex predecessor = edge.getSource().getProducer();
                        if (predecessor == null || predecessor.getID() == null) {
                            continue;
                        }
                        String inputId = predecessor.getID().toString();

                        if (edge.getSource().getResultType() == null
                                || edge.getSource().getResultType().name() == null) {
                            continue;
                        }
                        String exchange = edge.getSource().getResultType().name().toLowerCase();
                        String shipStrategy = edge.getShipStrategyName();
                        String preProcessingOperation = edge.getPreProcessingOperationName();
                        String operatorLevelCaching = edge.getOperatorLevelCachingDescription();

                        inputs.add(
                                new JobPlanInfo.Plan.Node.Input(
                                        inputId,
                                        inputNum,
                                        exchange,
                                        shipStrategy,
                                        preProcessingOperation,
                                        operatorLevelCaching));
                    }
                }
                nodes.add(
                        new JobPlanInfo.Plan.Node(
                                vertexID.toString(),
                                operator,
                                parallelism,
                                operatorDescr,
                                description,
                                new JobPlanInfo.RawJson(optimizerProps),
                                inputs));
            }

            return new JobPlanInfo.Plan(jobID.toString(), jobName, jobType.name(), nodes);
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate plan", e);
        }
    }

@Override
    public Collection<RequestSlotMatch> matchRequestsAndSlots(
            Collection<? extends PhysicalSlot> slots,
            Collection<PendingRequest> pendingRequests,
            Map<ResourceID, TaskExecutionLoad> taskExecutionLoadMap) {
        final Collection<RequestSlotMatch> requestSlotMatches = new ArrayList<>();

        final Map<AllocationID, PhysicalSlot> freeSlots =
                slots.stream()
                        .collect(
                                Collectors.toMap(
                                        PhysicalSlot::getAllocationId, Function.identity()));

        final Map<SlotRequestId, PendingRequest> pendingRequestsWithPreferredAllocations =
                new HashMap<>();
        final List<PendingRequest> unmatchedRequests = new ArrayList<>();

        // Split requests into those that have preferred allocations and those that don't have
        for (PendingRequest pendingRequest : pendingRequests) {
            if (pendingRequest.getPreferredAllocations().isEmpty()) {
                unmatchedRequests.add(pendingRequest);
            } else {
                pendingRequestsWithPreferredAllocations.put(
                        pendingRequest.getSlotRequestId(), pendingRequest);
            }
        }

        final Iterator<PhysicalSlot> freeSlotsIterator = freeSlots.values().iterator();
        // Match slots and pending requests based on preferred allocation
        while (freeSlotsIterator.hasNext() && !pendingRequestsWithPreferredAllocations.isEmpty()) {
            final PhysicalSlot freeSlot = freeSlotsIterator.next();

            final Iterator<PendingRequest> pendingRequestIterator =
                    pendingRequestsWithPreferredAllocations.values().iterator();

            while (pendingRequestIterator.hasNext()) {
                final PendingRequest pendingRequest = pendingRequestIterator.next();

                if (freeSlot.getResourceProfile().isMatching(pendingRequest.getResourceProfile())
                        && pendingRequest
                                .getPreferredAllocations()
                                .contains(freeSlot.getAllocationId())) {
                    requestSlotMatches.add(RequestSlotMatch.createFor(pendingRequest, freeSlot));
                    TaskExecutionLoad deltaLoad = pendingRequest.getTaskExecutionLoad();
                    taskExecutionLoadMap.compute(
                            freeSlot.getTaskManagerLocation().getResourceID(),
                            (ignoredId, oldLoad) ->
                                    oldLoad == null ? deltaLoad : deltaLoad.merge(oldLoad));
                    pendingRequestIterator.remove();
                    freeSlotsIterator.remove();
                    break;
                }
            }
        }

        unmatchedRequests.addAll(pendingRequestsWithPreferredAllocations.values());
        if (!freeSlots.isEmpty() && !unmatchedRequests.isEmpty()) {
            requestSlotMatches.addAll(
                    rollbackStrategy.matchRequestsAndSlots(
                            freeSlots.values(), unmatchedRequests, taskExecutionLoadMap));
        }

        return requestSlotMatches;
    }

public static InetAddress findConnectingAddress(
            InetSocketAddress targetAddress, long maxWaitMillis, long startLoggingAfter)
            throws IOException {
        if (targetAddress == null) {
            throw new NullPointerException("targetAddress must not be null");
        }
        if (maxWaitMillis <= 0) {
            throw new IllegalArgumentException("Max wait time must be positive");
        }

        final long startTimeNanos = System.nanoTime();

        long currentSleepTime = MIN_SLEEP_TIME;
        long elapsedTimeMillis = 0;

        final List<AddressDetectionState> strategies =
                Collections.unmodifiableList(
                        Arrays.asList(
                                AddressDetectionState.LOCAL_HOST,
                                AddressDetectionState.ADDRESS,
                                AddressDetectionState.FAST_CONNECT,
                                AddressDetectionState.SLOW_CONNECT));

        // loop while there is time left
        while (elapsedTimeMillis < maxWaitMillis) {
            boolean logging = elapsedTimeMillis >= startLoggingAfter;
            if (logging) {
                LOG.info("Trying to connect to " + targetAddress);
            }

            // Try each strategy in order
            for (AddressDetectionState strategy : strategies) {
                InetAddress address = findAddressUsingStrategy(strategy, targetAddress, logging);
                if (address != null) {
                    return address;
                }
            }

            // we have made a pass with all strategies over all interfaces
            // sleep for a while before we make the next pass
            elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;

            long toWait = Math.min(maxWaitMillis - elapsedTimeMillis, currentSleepTime);
            if (toWait > 0) {
                if (logging) {
                    LOG.info("Could not connect. Waiting for {} msecs before next attempt", toWait);
                } else {
                    LOG.debug(
                            "Could not connect. Waiting for {} msecs before next attempt", toWait);
                }

                try {
                    Thread.sleep(toWait);
                } catch (InterruptedException e) {
                    throw new IOException("Connection attempts have been interrupted.");
                }
            }

            // increase the exponential backoff timer
            currentSleepTime = Math.min(2 * currentSleepTime, MAX_SLEEP_TIME);
        }

        // our attempts timed out. use the heuristic fallback
        LOG.warn(
                "Could not connect to {}. Selecting a local address using heuristics.",
                targetAddress);
        InetAddress heuristic =
                findAddressUsingStrategy(AddressDetectionState.HEURISTIC, targetAddress, true);
        if (heuristic != null) {
            return heuristic;
        } else {
            LOG.warn(
                    "Could not find any IPv4 address that is not loopback or link-local. Using localhost address.");
            return InetAddress.getLocalHost();
        }
    }

public InetAddress findConnectingAddress(Duration timeout, Duration startLoggingAfter)
                throws LeaderRetrievalException {

            final long startTimeNanos = System.nanoTime();
            long currentSleepTime = MIN_SLEEP_TIME;
            long elapsedTimeMillis = 0;
            InetSocketAddress targetAddress = null;

            try {
                while (elapsedTimeMillis < timeout.toMillis()) {

                    long maxTimeout = timeout.toMillis() - elapsedTimeMillis;

                    synchronized (retrievalLock) {
                        if (exception != null) {
                            throw exception;
                        }

                        if (retrievalState == LeaderRetrievalState.NOT_RETRIEVED) {
                            try {
                                retrievalLock.wait(maxTimeout);
                            } catch (InterruptedException e) {
                                throw new Exception(
                                        "Finding connecting address was interrupted"
                                                + "while waiting for the leader retrieval.");
                            }
                        } else if (retrievalState == LeaderRetrievalState.NEWLY_RETRIEVED) {
                            targetAddress = rpcSystemUtils.getInetSocketAddressFromRpcUrl(rpcURL);

                            LOG.debug(
                                    "Retrieved new target address {} for RPC URL {}.",
                                    targetAddress,
                                    rpcURL);

                            retrievalState = LeaderRetrievalState.RETRIEVED;

                            currentSleepTime = MIN_SLEEP_TIME;
                        } else {
                            currentSleepTime = Math.min(2 * currentSleepTime, MAX_SLEEP_TIME);
                        }
                    }

                    if (targetAddress != null) {
                        AddressDetectionState strategy = AddressDetectionState.LOCAL_HOST;

                        boolean logging = elapsedTimeMillis >= startLoggingAfter.toMillis();
                        if (logging) {
                            LOG.info("Trying to connect to address {}", targetAddress);
                        }

                        do {
                            InetAddress address =
                                    ConnectionUtils.findAddressUsingStrategy(
                                            strategy, targetAddress, logging);
                            if (address != null) {
                                return address;
                            }

                            // pick the next strategy
                            switch (strategy) {
                                case LOCAL_HOST:
                                    strategy = AddressDetectionState.ADDRESS;
                                    break;
                                case ADDRESS:
                                    strategy = AddressDetectionState.FAST_CONNECT;
                                    break;
                                case FAST_CONNECT:
                                    strategy = AddressDetectionState.SLOW_CONNECT;
                                    break;
                                case SLOW_CONNECT:
                                    strategy = null;
                                    break;
                                default:
                                    throw new RuntimeException("Unsupported strategy: " + strategy);
                            }
                        } while (strategy != null);
                    }

                    elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;

                    long timeToWait =
                            Math.min(
                                    Math.max(timeout.toMillis() - elapsedTimeMillis, 0),
                                    currentSleepTime);

                    if (timeToWait > 0) {
                        synchronized (retrievalLock) {
                            try {
                                retrievalLock.wait(timeToWait);
                            } catch (InterruptedException e) {
                                throw new Exception(
                                        "Finding connecting address was interrupted while pausing.");
                            }
                        }

                        elapsedTimeMillis = (System.nanoTime() - startTimeNanos) / 1_000_000;
                    }
                }

                InetAddress heuristic = null;

                if (targetAddress != null) {
                    LOG.warn(
                            "Could not connect to {}. Selecting a local address using heuristics.",
                            targetAddress);
                    heuristic =
                            findAddressUsingStrategy(
                                    AddressDetectionState.HEURISTIC, targetAddress, true);
                }

                if (heuristic != null) {
                    return heuristic;
                } else {
                    LOG.warn(
                            "Could not find any IPv4 address that is not loopback or link-local. Using localhost address.");
                    return InetAddress.getLocalHost();
                }
            } catch (Exception e) {
                throw new LeaderRetrievalException(
                        "Could not retrieve the connecting address to the "
                                + "current leader with the pekko URL "
                                + rpcURL
                                + ".",
                        e);
            }
        }

