        if (memorySegments.size() < MIN_NUM_MEMORY_SEGMENTS) {
            throw new IllegalArgumentException(
                    "Too few memory segments provided. Hash Join needs at least "
                            + MIN_NUM_MEMORY_SEGMENTS
