public static boolean isAssignable(Class<?> cls, Class<?> toClass, Autoboxing autoboxing) {
        if (toClass == null) {
            return false;
        }
        // have to check for null, as isAssignableFrom doesn't
        if (cls == null) {
            return !toClass.isPrimitive();
        }
        // autoboxing:
        if (autoboxing != Autoboxing.NONE) {
            if (cls.isPrimitive() && !toClass.isPrimitive()) {
                cls = primitiveToWrapper(cls);
                if (cls == null) {
                    return false;
                }
            }
            if (autoboxing == Autoboxing.JVM) {
                if (toClass.isPrimitive() && !cls.isPrimitive()) {
                    cls = wrapperToPrimitive(cls);
                    if (cls == null) {
                        return false;
                    }
                }
            }
        }
        if (cls.equals(toClass)) {
            return true;
        }
        if (cls.isPrimitive()) {
            if (!toClass.isPrimitive()) {
                return false;
            }
            if (Integer.TYPE.equals(cls)) {
                return Long.TYPE.equals(toClass)
                        || Float.TYPE.equals(toClass)
                        || Double.TYPE.equals(toClass);
            }
            if (Long.TYPE.equals(cls)) {
                return Float.TYPE.equals(toClass) || Double.TYPE.equals(toClass);
            }
            if (Boolean.TYPE.equals(cls)) {
                return false;
            }
            if (Double.TYPE.equals(cls)) {
                return false;
            }
            if (Float.TYPE.equals(cls)) {
                return Double.TYPE.equals(toClass);
            }
            if (Character.TYPE.equals(cls)) {
                return Integer.TYPE.equals(toClass)
                        || Long.TYPE.equals(toClass)
                        || Float.TYPE.equals(toClass)
                        || Double.TYPE.equals(toClass);
            }
            if (Short.TYPE.equals(cls)) {
                return Integer.TYPE.equals(toClass)
                        || Long.TYPE.equals(toClass)
                        || Float.TYPE.equals(toClass)
                        || Double.TYPE.equals(toClass);
            }
            if (Byte.TYPE.equals(cls)) {
                return Short.TYPE.equals(toClass)
                        || Integer.TYPE.equals(toClass)
                        || Long.TYPE.equals(toClass)
                        || Float.TYPE.equals(toClass)
                        || Double.TYPE.equals(toClass);
            }
            // should never get here
            return false;
        }
        return toClass.isAssignableFrom(cls);
    }

@Override
    public Optional<DataType> inferArgumentType(
            CallContext callContext, int argumentPos, boolean throwOnFailure) {
        final List<DataType> argumentDataTypes = callContext.getArgumentDataTypes();
        final LogicalType collectionType = argumentDataTypes.get(0).getLogicalType();
        final DataType indexType = argumentDataTypes.get(1);

        if (collectionType.is(LogicalTypeRoot.ARRAY)) {
            if (indexType.getLogicalType().is(LogicalTypeFamily.INTEGER_NUMERIC)) {

                if (callContext.isArgumentLiteral(1)) {
                    Optional<Integer> literalVal = callContext.getArgumentValue(1, Integer.class);
                    if (literalVal.isPresent() && literalVal.get() <= 0) {
                        return callContext.fail(
                                throwOnFailure,
                                "The provided index must be a valid SQL index starting from 1, but was '%s'",
                                literalVal.get());
                    }
                }

                return Optional.of(indexType);
            } else {
                return callContext.fail(
                        throwOnFailure, "Array can be indexed only using an INTEGER NUMERIC type.");
            }
        }

        if (collectionType.is(LogicalTypeRoot.MAP)) {
            MapType mapType = (MapType) collectionType;
            if (LogicalTypeCasts.supportsImplicitCast(
                    indexType.getLogicalType(), mapType.getKeyType())) {
                final KeyValueDataType mapDataType = (KeyValueDataType) argumentDataTypes.get(0);
                return Optional.of(mapDataType.getKeyDataType());
            } else {
                return callContext.fail(
                        throwOnFailure,
                        "Expected index for a MAP to be of type: %s",
                        mapType.getKeyType());
            }
        }

        if (collectionType.is(LogicalTypeRoot.VARIANT)) {
            if (indexType.getLogicalType().is(LogicalTypeFamily.INTEGER_NUMERIC)) {

                if (callContext.isArgumentLiteral(1)) {
                    Optional<Integer> literalVal = callContext.getArgumentValue(1, Integer.class);
                    if (literalVal.isPresent() && literalVal.get() <= 0) {
                        return callContext.fail(
                                throwOnFailure,
                                "The provided index must be a valid SQL index starting from 1, but was '%s'",
                                literalVal.get());
                    }
                }

                return Optional.of(indexType);
            } else if (indexType.getLogicalType().is(LogicalTypeFamily.CHARACTER_STRING)) {
                return Optional.of(indexType);
            } else {
                return callContext.fail(
                        throwOnFailure,
                        "Incorrect type %s supplied for the variant value. Variant values can only be accessed with a CHARACTER STRING map key or an INTEGER NUMERIC array index.",
                        indexType.getLogicalType().toString());
            }
        }

        return Optional.empty();
    }

@Override
    public Optional<List<DataType>> inferInputTypes(
            CallContext callContext, boolean throwOnFailure) {
        final List<DataType> args = callContext.getArgumentDataTypes();
        final LogicalType leftTimePoint = args.get(0).getLogicalType();
        final LogicalType leftTemporal = args.get(1).getLogicalType();
        final LogicalType rightTimePoint = args.get(2).getLogicalType();
        final LogicalType rightTemporal = args.get(3).getLogicalType();

        if (!leftTimePoint.is(LogicalTypeFamily.DATETIME)) {
            return callContext.fail(
                    throwOnFailure,
                    "TEMPORAL_OVERLAPS requires 1st argument 'leftTimePoint' to be a DATETIME type, but is %s",
                    leftTimePoint);
        }
        if (!rightTimePoint.is(LogicalTypeFamily.DATETIME)) {
            return callContext.fail(
                    throwOnFailure,
                    "TEMPORAL_OVERLAPS requires 3rd argument 'rightTimePoint' to be a DATETIME type, but is %s",
                    rightTimePoint);
        }

        if (!leftTimePoint.equals(rightTimePoint)) {
            return callContext.fail(
                    throwOnFailure,
                    "TEMPORAL_OVERLAPS requires 'leftTimePoint' and 'rightTimePoint' arguments to be of the same type, but is %s != %s",
                    leftTimePoint,
                    rightTimePoint);
        }

        // leftTemporal is point, then it must be comparable with leftTimePoint
        if (leftTemporal.is(LogicalTypeFamily.DATETIME)) {
            if (!leftTemporal.equals(leftTimePoint)) {
                return callContext.fail(
                        throwOnFailure,
                        "TEMPORAL_OVERLAPS requires 'leftTemporal' and 'leftTimePoint' arguments to be of the same type if 'leftTemporal' is a DATETIME, but is %s != %s",
                        leftTemporal,
                        leftTimePoint);
            }
        } else if (!leftTemporal.is(LogicalTypeFamily.INTERVAL)) {
            return callContext.fail(
                    throwOnFailure,
                    "TEMPORAL_OVERLAPS requires 2nd argument 'leftTemporal' to be DATETIME or INTERVAL type, but is %s",
                    leftTemporal);
        }

        // rightTemporal is point, then it must be comparable with rightTimePoint
        if (rightTemporal.is(LogicalTypeFamily.DATETIME)) {
            if (!rightTemporal.equals(rightTimePoint)) {
                return callContext.fail(
                        throwOnFailure,
                        "TEMPORAL_OVERLAPS requires 'rightTemporal' and 'rightTimePoint' arguments to be of the same type if 'rightTemporal' is a DATETIME, but is %s != %s",
                        rightTemporal,
                        rightTimePoint);
            }
        } else if (!rightTemporal.is(LogicalTypeFamily.INTERVAL)) {
            return callContext.fail(
                    throwOnFailure,
                    "TEMPORAL_OVERLAPS requires 4th argument 'rightTemporal' to be DATETIME or INTERVAL type, but is %s",
                    rightTemporal);
        }

        return Optional.of(args);
    }

@Override
    public Optional<DataType> inferType(CallContext callContext) {
        List<DataType> argumentTypes = callContext.getArgumentDataTypes();
        int argCount = argumentTypes.size();

        if (argCount < 1 || argCount > 3) {
            throw new ValidationException(
                    "Unsupported argument type. "
                            + "TO_TIMESTAMP_LTZ requires 1 to 3 arguments, but "
                            + argCount
                            + " were provided.");
        }

        LogicalType firstType = argumentTypes.get(EPOCH_OR_TIMESTAMP_ARG).getLogicalType();
        LogicalTypeRoot firstTypeRoot = firstType.getTypeRoot();
        int outputPrecision = DEFAULT_PRECISION;

        switch (argCount) {
            case 1:
                if (!isCharacterType(firstTypeRoot) && !firstType.is(LogicalTypeFamily.NUMERIC)) {
                    throw new ValidationException(
                            "Unsupported argument type. "
                                    + "When taking 1 argument, TO_TIMESTAMP_LTZ accepts an argument of type <VARCHAR>, <CHAR>, or <NUMERIC>.");
                }
                break;
            case 2:
                LogicalType secondType =
                        argumentTypes.get(PRECISION_OR_FORMAT_ARG).getLogicalType();
                LogicalTypeRoot secondTypeRoot = secondType.getTypeRoot();
                if (firstType.is(LogicalTypeFamily.NUMERIC)) {
                    if (secondTypeRoot != LogicalTypeRoot.INTEGER) {
                        throw new ValidationException(
                                "Unsupported argument type. "
                                        + "TO_TIMESTAMP_LTZ(<NUMERIC>, <INTEGER>) requires the second argument to be <INTEGER>.");
                    }
                    outputPrecision = inferPrecisionFromIntegerArg(callContext);
                } else if (isCharacterType(firstTypeRoot)) {
                    if (!isCharacterType(secondTypeRoot)) {
                        throw new ValidationException(
                                "Unsupported argument type. "
                                        + "If the first argument is of type <VARCHAR> or <CHAR>, TO_TIMESTAMP_LTZ requires the second argument to be of type <VARCHAR> or <CHAR>.");
                    }
                    outputPrecision = inferPrecisionFromFormat(callContext);
                } else {
                    throw new ValidationException(
                            "Unsupported argument type. "
                                    + "When taking 2 arguments, TO_TIMESTAMP_LTZ requires the first argument to be of type <VARCHAR>, <CHAR>, or <NUMERIC>.");
                }
                break;
            case 3:
                if (!isCharacterType(firstTypeRoot)
                        || !isCharacterType(
                                argumentTypes
                                        .get(PRECISION_OR_FORMAT_ARG)
                                        .getLogicalType()
                                        .getTypeRoot())
                        || !isCharacterType(
                                argumentTypes.get(TIMEZONE_ARG).getLogicalType().getTypeRoot())) {
                    throw new ValidationException(
                            "Unsupported argument type. "
                                    + "When taking 3 arguments, TO_TIMESTAMP_LTZ requires all three arguments to be of type <VARCHAR> or <CHAR>.");
                }
                outputPrecision = inferPrecisionFromFormat(callContext);
        }

        return Optional.of(DataTypes.TIMESTAMP_LTZ(outputPrecision).nullable());
    }

public static Class<?> toInternalConversionClass(LogicalType type) {
        // ordered by type root definition
        switch (type.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                return StringData.class;
            case BOOLEAN:
                return Boolean.class;
            case BINARY:
            case VARBINARY:
            case UUID:
                return byte[].class;
            case DECIMAL:
                return DecimalData.class;
            case TINYINT:
                return Byte.class;
            case SMALLINT:
                return Short.class;
            case INTEGER:
            case DATE:
            case TIME_WITHOUT_TIME_ZONE:
            case INTERVAL_YEAR_MONTH:
                return Integer.class;
            case BIGINT:
            case INTERVAL_DAY_TIME:
                return Long.class;
            case FLOAT:
                return Float.class;
            case DOUBLE:
                return Double.class;
            case TIMESTAMP_WITHOUT_TIME_ZONE:
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                return TimestampData.class;
            case TIMESTAMP_WITH_TIME_ZONE:
                throw new UnsupportedOperationException("Unsupported type: " + type);
            case ARRAY:
                return ArrayData.class;
            case MULTISET:
            case MAP:
                return MapData.class;
            case ROW:
            case STRUCTURED_TYPE:
                return RowData.class;
            case DISTINCT_TYPE:
                return toInternalConversionClass(((DistinctType) type).getSourceType());
            case RAW:
                return RawValueData.class;
            case NULL:
                return Object.class;
            case DESCRIPTOR:
                return ColumnList.class;
            case VARIANT:
                return Variant.class;
            case BITMAP:
                return Bitmap.class;
            case SYMBOL:
            case UNRESOLVED:
            default:
                throw new IllegalArgumentException("Illegal type: " + type);
        }
    }

public static Optional<DataType> extractDataType(Object value) {
        if (value == null) {
            return Optional.empty();
        }

        DataType convertedDataType = null;

        if (value instanceof String) {
            convertedDataType = convertToCharType((String) value);
        }

        // byte arrays have higher priority than regular arrays
        else if (value instanceof byte[]) {
            convertedDataType = convertToBinaryType((byte[]) value);
        } else if (value instanceof BigDecimal) {
            convertedDataType = convertToDecimalType((BigDecimal) value);
        } else if (value instanceof java.time.LocalTime) {
            convertedDataType = convertToTimeType((java.time.LocalTime) value);
        } else if (value instanceof java.time.LocalDateTime) {
            convertedDataType = convertToTimestampType(((java.time.LocalDateTime) value).getNano());
        } else if (value instanceof java.sql.Timestamp) {
            convertedDataType = convertToTimestampType(((java.sql.Timestamp) value).getNanos());
        } else if (value instanceof java.time.ZonedDateTime) {
            convertedDataType =
                    convertToZonedTimestampType(((java.time.ZonedDateTime) value).getNano());
        } else if (value instanceof java.time.OffsetDateTime) {
            convertedDataType =
                    convertToZonedTimestampType(((java.time.OffsetDateTime) value).getNano());
        } else if (value instanceof java.time.Instant) {
            convertedDataType =
                    convertToLocalZonedTimestampType(((java.time.Instant) value).getNano());
        } else if (value instanceof java.time.Period) {
            convertedDataType = convertToYearMonthIntervalType((java.time.Period) value);
        } else if (value instanceof java.time.Duration) {
            final java.time.Duration duration = (java.time.Duration) value;
            convertedDataType = convertToDayTimeIntervalType(duration.toDays(), duration.getNano());
        } else if (value instanceof Object[]) {
            // don't let the class-based extraction kick in if array elements differ
            return convertToArrayType((Object[]) value)
                    .map(dt -> dt.notNull().bridgedTo(value.getClass()));
        }

        final Optional<DataType> resultType;
        if (convertedDataType != null) {
            resultType = Optional.of(convertedDataType);
        } else {
            // class-based extraction is possible for BOOLEAN, TINYINT, SMALLINT, INT, FLOAT,
            // DOUBLE,
            // DATE, TIME with java.sql.Time, and arrays of primitive types
            resultType = ClassDataTypeConverter.extractDataType(value.getClass());
        }
        return resultType.map(
                dt -> {
                    final DataType notNullDataType = dt.notNull();
                    // Because they are interfaces, and we want to avoid bridgeTo internal
                    // conversion classes.
                    if (value instanceof Variant || value instanceof Bitmap) {
                        return notNullDataType;
                    }
                    return notNullDataType.bridgedTo(value.getClass());
                });
    }

public static Integer parseTime(final String v) {
        final int start = 0;
        final int colon1 = v.indexOf(':', start);
        // timezone hh:mm:ss[.ssssss][[+|-]hh:mm:ss]
        // refer https://www.w3.org/TR/NOTE-datetime
        int timezoneHour;
        int timezoneMinute;
        int hour;
        int minute;
        int second;
        int milli;
        int operator = -1;
        int end = v.length();
        int timezone = v.indexOf('-', start);
        if (timezone < 0) {
            timezone = v.indexOf('+', start);
            operator = 1;
        }
        if (timezone < 0) {
            timezoneHour = 0;
            timezoneMinute = 0;
        } else {
            end = timezone;
            final int colon3 = v.indexOf(':', timezone);
            if (colon3 < 0) {
                if (!isInteger(v.substring(timezone + 1).trim())) {
                    return null;
                }
                timezoneHour = Integer.parseInt(v.substring(timezone + 1).trim());
                timezoneMinute = 0;
            } else {
                if (!isInteger(v.substring(timezone + 1, colon3).trim())) {
                    return null;
                }
                timezoneHour = Integer.parseInt(v.substring(timezone + 1, colon3).trim());
                if (!isInteger(v.substring(colon3 + 1).trim())) {
                    return null;
                }
                timezoneMinute = Integer.parseInt(v.substring(colon3 + 1).trim());
            }
        }
        if (colon1 < 0) {
            if (!isInteger(v.substring(start, end).trim())) {
                return null;
            }
            hour = Integer.parseInt(v.substring(start, end).trim());
            minute = 0;
            second = 0;
            milli = 0;
        } else {
            if (!isInteger(v.substring(start, colon1).trim())) {
                return null;
            }
            hour = Integer.parseInt(v.substring(start, colon1).trim());
            final int colon2 = v.indexOf(':', colon1 + 1);
            if (colon2 < 0) {
                if (!isInteger(v.substring(colon1 + 1, end).trim())) {
                    return null;
                }
                minute = Integer.parseInt(v.substring(colon1 + 1, end).trim());
                second = 0;
                milli = 0;
            } else {
                if (!isInteger(v.substring(colon1 + 1, colon2).trim())) {
                    return null;
                }
                minute = Integer.parseInt(v.substring(colon1 + 1, colon2).trim());
                int dot = v.indexOf('.', colon2);
                if (dot < 0) {
                    if (!isInteger(v.substring(colon2 + 1, end).trim())) {
                        return null;
                    }
                    second = Integer.parseInt(v.substring(colon2 + 1, end).trim());
                    milli = 0;
                } else {
                    if (!isInteger(v.substring(colon2 + 1, dot).trim())) {
                        return null;
                    }
                    second = Integer.parseInt(v.substring(colon2 + 1, dot).trim());
                    milli = parseFraction(v.substring(dot + 1, end).trim());
                }
            }
        }

        if (!isValidTime(hour, minute, second)) {
            return null;
        }

        hour += operator * timezoneHour;
        minute += operator * timezoneMinute;
        return hour * (int) MILLIS_PER_HOUR
                + minute * (int) MILLIS_PER_MINUTE
                + second * (int) MILLIS_PER_SECOND
                + milli;
    }

static int[] columnWidthsByType(
            List<Column> columns,
            int maxColumnWidth,
            boolean printNullAsEmpty,
            boolean printRowKind) {
        // fill width with field names first
        final int[] colWidths = columns.stream().mapToInt(col -> col.getName().length()).toArray();

        // determine proper column width based on types
        for (int i = 0; i < columns.size(); ++i) {
            LogicalType type = columns.get(i).getDataType().getLogicalType();
            int len;
            switch (type.getTypeRoot()) {
                case TINYINT:
                    len = TinyIntType.PRECISION + 1; // extra for negative value
                    break;
                case SMALLINT:
                    len = SmallIntType.PRECISION + 1; // extra for negative value
                    break;
                case INTEGER:
                    len = IntType.PRECISION + 1; // extra for negative value
                    break;
                case BIGINT:
                    len = BigIntType.PRECISION + 1; // extra for negative value
                    break;
                case DECIMAL:
                    len =
                            ((DecimalType) type).getPrecision()
                                    + 2; // extra for negative value and decimal point
                    break;
                case BOOLEAN:
                    len = 5; // "true" or "false"
                    break;
                case DATE:
                    len = 10; // e.g. 9999-12-31
                    break;
                case TIME_WITHOUT_TIME_ZONE:
                    int precision = ((TimeType) type).getPrecision();
                    len = precision == 0 ? 8 : precision + 9; // 23:59:59[.999999999]
                    break;
                case TIMESTAMP_WITHOUT_TIME_ZONE:
                    precision = ((TimestampType) type).getPrecision();
                    len = timestampTypeColumnWidth(precision);
                    break;
                case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                    precision = ((LocalZonedTimestampType) type).getPrecision();
                    len = timestampTypeColumnWidth(precision);
                    break;
                default:
                    len = maxColumnWidth;
            }

            // adjust column width with potential null values
            len = printNullAsEmpty ? len : Math.max(len, PrintStyle.NULL_VALUE.length());
            colWidths[i] = Math.max(colWidths[i], len);
        }

        // add an extra column for row kind if necessary
        if (printRowKind) {
            final int[] ret = new int[columns.size() + 1];
            ret[0] = ROW_KIND_COLUMN.length();
            System.arraycopy(colWidths, 0, ret, 1, columns.size());
            return ret;
        } else {
            return colWidths;
        }
    }

