                        typeFactory.createSqlType(SqlTypeName.CHAR, 0),
                        SqlTypeName.CHAR);
        this.constantNull =
                makeLiteral(null, typeFactory.createSqlType(SqlTypeName.NULL), SqlTypeName.NULL);
