@Override
    protected String generateCodeBlockInternal(
            CodeGeneratorCastRule.Context context,
            String inputTerm,
            String returnVariable,
            LogicalType inputLogicalType,
            LogicalType targetLogicalType) {
        final CodeWriter writer = new CastRuleUtils.CodeWriter();
        switch (targetLogicalType.getTypeRoot()) {
            case BOOLEAN:
                writer.assignStmt(returnVariable, methodCall(inputTerm, "getBoolean"));
                break;
            case TINYINT:
            case SMALLINT:
            case INTEGER:
            case BIGINT:
                writer.assignStmt(
                        returnVariable,
                        cast(
                                primitiveTypeTermForType(targetLogicalType),
                                staticCall(
                                        VariantCastUtils.class,
                                        "toIntegral",
                                        inputTerm,
                                        // A long literal needs the suffix to compile, since
                                        // Long.MIN_VALUE does not fit an int literal.
                                        integralMin(targetLogicalType) + "L",
                                        integralMax(targetLogicalType) + "L",
                                        strLiteral(targetLogicalType.getTypeRoot().name()))));
                break;
            case FLOAT:
                writer.assignStmt(
                        returnVariable, staticCall(VariantCastUtils.class, "toFloat", inputTerm));
                break;
            case DOUBLE:
                writer.assignStmt(
                        returnVariable, staticCall(VariantCastUtils.class, "toDouble", inputTerm));
                break;
            case DECIMAL:
                final DecimalType decimalType = (DecimalType) targetLogicalType;
                writer.assignStmt(
                        returnVariable,
                        staticCall(
                                VariantCastUtils.class,
                                "toDecimal",
                                inputTerm,
                                decimalType.getPrecision(),
                                decimalType.getScale()));
                break;
            case BINARY:
            case VARBINARY:
                writer.assignStmt(
                        returnVariable,
                        staticCall(
                                VariantCastUtils.class,
                                "toBytes",
                                inputTerm,
                                LogicalTypeChecks.getLength(targetLogicalType),
                                targetLogicalType.is(LogicalTypeRoot.BINARY)));
                break;
            case DATE:
                writer.assignStmt(
                        returnVariable,
                        cast("int", methodCall(methodCall(inputTerm, "getDate"), "toEpochDay")));
                break;
            case TIME_WITHOUT_TIME_ZONE:
                writer.assignStmt(
                        returnVariable,
                        staticCall(
                                VariantCastUtils.class,
                                "toTime",
                                inputTerm,
                                LogicalTypeChecks.getPrecision(targetLogicalType)));
                break;
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                writer.assignStmt(
                        returnVariable,
                        staticCall(
                                VariantCastUtils.class,
                                "toTimestamp",
                                inputTerm,
                                LogicalTypeChecks.getPrecision(targetLogicalType)));
                break;
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                writer.assignStmt(
                        returnVariable,
                        staticCall(
                                VariantCastUtils.class,
                                "toTimestampLtz",
                                inputTerm,
                                LogicalTypeChecks.getPrecision(targetLogicalType)));
                break;
            case UUID:
                writer.assignStmt(
                        returnVariable, staticCall(VariantCastUtils.class, "toUuid", inputTerm));
                break;
            default:
                throw new IllegalArgumentException(
                        "Unsupported target type for casting from VARIANT: " + targetLogicalType);
        }
        return writer.toString();
    }

@Override
    public Operation convertSqlNode(SqlAnalyzeTable analyzeTable, ConvertContext context) {
        UnresolvedIdentifier unresolvedIdentifier =
                UnresolvedIdentifier.of(analyzeTable.fullTableName());
        CatalogManager catalogManager = context.getCatalogManager();
        ObjectIdentifier tableIdentifier = catalogManager.qualifyIdentifier(unresolvedIdentifier);
        Optional<ContextResolvedTable> optionalCatalogTable =
                catalogManager.getTable(tableIdentifier);
        if (optionalCatalogTable.isEmpty() || optionalCatalogTable.get().isTemporary()) {
            throw new ValidationException(
                    String.format(
                            "Table %s doesn't exist or is a temporary table.", tableIdentifier));
        }
        CatalogBaseTable baseTable = optionalCatalogTable.get().getResolvedTable();
        ValidationUtils.validateTableKind(
                baseTable, CatalogBaseTable.TableKind.TABLE, "analyze table");

        CatalogTable table = (CatalogTable) baseTable;
        ResolvedSchema schema =
                baseTable.getUnresolvedSchema().resolve(catalogManager.getSchemaResolver());

        LinkedHashMap<String, String> partitions = analyzeTable.getPartitions();
        List<CatalogPartitionSpec> targetPartitionSpecs = null;
        if (table.isPartitioned()) {
            if (!partitions.keySet().equals(new HashSet<>(table.getPartitionKeys()))) {
                throw new ValidationException(
                        String.format(
                                "Invalid ANALYZE TABLE statement. For partition table, all partition keys should be specified explicitly. "
                                        + "The given partition keys: [%s] are not match the target partition keys: [%s].",
                                String.join(",", partitions.keySet()),
                                String.join(",", table.getPartitionKeys())));
            }

            try {
                targetPartitionSpecs =
                        getPartitionSpecs(tableIdentifier, schema, partitions, catalogManager);
            } catch (Exception e) {
                throw new ValidationException(e.getMessage(), e);
            }
        } else if (!partitions.isEmpty()) {
            throw new ValidationException(
                    String.format(
                            "Invalid ANALYZE TABLE statement. Table: %s is not a partition table, while partition values are given.",
                            tableIdentifier));
        }

        List<String> columns = analyzeTable.getColumnNames();
        List<Column> targetColumns;
        if (analyzeTable.isAllColumns()) {
            Preconditions.checkArgument(columns.isEmpty());
            // computed column and metadata column will be ignored
            targetColumns =
                    schema.getColumns().stream()
                            .filter(Column::isPhysical)
                            .collect(Collectors.toList());
        } else if (!columns.isEmpty()) {
            targetColumns =
                    columns.stream()
                            .map(
                                    c -> {
                                        Optional<Column> colOpt = schema.getColumn(c);
                                        if (colOpt.isEmpty()) {
                                            throw new ValidationException(
                                                    String.format(
                                                            "Column: %s does not exist in the table: %s.",
                                                            c, tableIdentifier));
                                        }
                                        Column col = colOpt.get();
                                        if (col instanceof Column.ComputedColumn) {
                                            throw new ValidationException(
                                                    String.format(
                                                            "Column: %s is a computed column, ANALYZE TABLE does not support computed column.",
                                                            c));
                                        } else if (col instanceof Column.MetadataColumn) {
                                            throw new ValidationException(
                                                    String.format(
                                                            "Column: %s is a metadata column, ANALYZE TABLE does not support metadata column.",
                                                            c));
                                        } else if (col instanceof Column.PhysicalColumn) {
                                            return col;
                                        } else {
                                            throw new ValidationException(
                                                    "Unknown column class: "
                                                            + col.getClass().getSimpleName());
                                        }
                                    })
                            .collect(Collectors.toList());
        } else {
            targetColumns = Collections.emptyList();
        }

        return new AnalyzeTableOperation(tableIdentifier, targetPartitionSpecs, targetColumns);
    }

public static List<RelCollation> project(
            RelMetadataQuery mq, RelNode input, List<? extends RexNode> projects) {
        final SortedSet<RelCollation> collations = new TreeSet<>();
        final List<RelCollation> inputCollations = mq.collations(input);
        if (inputCollations == null || inputCollations.isEmpty()) {
            return com.google.common.collect.ImmutableList.of();
        }
        final com.google.common.collect.Multimap<Integer, Integer> targets =
                com.google.common.collect.LinkedListMultimap.create();
        final Map<Integer, SqlMonotonicity> targetsWithMonotonicity = new HashMap<>();
        for (Ord<RexNode> project : Ord.<RexNode>zip(projects)) {
            if (project.e instanceof RexInputRef) {
                targets.put(((RexInputRef) project.e).getIndex(), project.i);
            } else if (project.e instanceof RexCall) {
                final RexCall call = (RexCall) project.e;
                final RexCallBinding binding =
                        RexCallBinding.create(
                                input.getCluster().getTypeFactory(), call, inputCollations);
                targetsWithMonotonicity.put(project.i, call.getOperator().getMonotonicity(binding));
            }
        }
        final List<RelFieldCollation> fieldCollations = new ArrayList<>();
        loop:
        for (RelCollation ic : inputCollations) {
            if (ic.getFieldCollations().isEmpty()) {
                continue;
            }
            fieldCollations.clear();
            for (RelFieldCollation ifc : ic.getFieldCollations()) {
                final Collection<Integer> integers = targets.get(ifc.getFieldIndex());
                if (integers.isEmpty()) {
                    continue loop; // cannot do this collation
                }
                fieldCollations.add(ifc.withFieldIndex(integers.iterator().next()));
            }
            assert !fieldCollations.isEmpty();
            collations.add(RelCollations.of(fieldCollations));
        }

        final List<RelFieldCollation> fieldCollationsForRexCalls = new ArrayList<>();
        for (Map.Entry<Integer, SqlMonotonicity> entry : targetsWithMonotonicity.entrySet()) {
            final SqlMonotonicity value = entry.getValue();
            switch (value) {
                case NOT_MONOTONIC:
                case CONSTANT:
                    break;
                default:
                    fieldCollationsForRexCalls.add(
                            new RelFieldCollation(
                                    entry.getKey(), RelFieldCollation.Direction.of(value)));
                    break;
            }
        }

        if (!fieldCollationsForRexCalls.isEmpty()) {
            collations.add(RelCollations.of(fieldCollationsForRexCalls));
        }

        return com.google.common.collect.ImmutableList.copyOf(collations);
    }

