@Override
    public ExecNodeGraph process(ExecNodeGraph execGraph, ProcessorContext context) {
        if (execGraph.getRootNodes().get(0) instanceof StreamExecNode) {
            throw new TableException("StreamExecNode is not supported yet");
        }
        JobManagerOptions.SchedulerType schedulerType =
                context.getPlanner()
                        .getExecEnv()
                        .getConfig()
                        .getSchedulerType()
                        .orElse(JobManagerOptions.SchedulerType.AdaptiveBatch);
        if (schedulerType != JobManagerOptions.SchedulerType.AdaptiveBatch) {
            return execGraph;
        }
        ReadableConfig tableConfig = context.getPlanner().getTableConfig();
        ExecNodeVisitor visitor =
                new AbstractExecNodeExactlyOnceVisitor() {
                    @Override
                    protected void visitNode(ExecNode<?> node) {
                        visitInputs(node);
                        if (node instanceof CommonExecExchange) {
                            return;
                        }
                        boolean changed = false;
                        List<ExecEdge> newEdges = new ArrayList<>(node.getInputEdges());
                        for (int i = 0; i < node.getInputProperties().size(); ++i) {
                            InputProperty inputProperty = node.getInputProperties().get(i);
                            RequiredDistribution requiredDistribution =
                                    inputProperty.getRequiredDistribution();
                            ExecEdge edge = node.getInputEdges().get(i);

                            if (requiredDistribution.getType() != DistributionType.HASH) {
                                boolean visitChild =
                                        requiredDistribution.getType()
                                                == DistributionType.SINGLETON;
                                if (!hasExchangeInput(edge)
                                        && hasSortInputForInputSortedNode(node)) {
                                    ExecEdge newEdge =
                                            addExchangeAndReconnectEdge(
                                                    tableConfig,
                                                    edge,
                                                    inputProperty,
                                                    true,
                                                    visitChild);
                                    newEdges.set(i, newEdge);
                                    changed = true;
                                }
                                continue;
                            }

                            if (!hasExchangeInput(edge)) {
                                ExecEdge newEdge;
                                if (isInputSortedNode(node)) {
                                    if (hasSortInputForInputSortedNode(node)) {
                                        // add Exchange with keep_input_as_is distribution as the
                                        // input of Sort
                                        ExecNode<?> sort = edge.getSource();
                                        ExecEdge newEdgeOfSort =
                                                addExchangeAndReconnectEdge(
                                                        tableConfig,
                                                        sort.getInputEdges().get(0),
                                                        inputProperty,
                                                        false,
                                                        true);
                                        sort.setInputEdges(
                                                Collections.singletonList(newEdgeOfSort));
                                    }

                                    // if operation chaining is disabled, this could mark sure the
                                    // sort node and its output can also be connected by
                                    // ForwardPartitioner
                                    newEdge =
                                            addExchangeAndReconnectEdge(
                                                    tableConfig, edge, inputProperty, true, true);
                                } else {
                                    // add Exchange with keep_input_as_is distribution as the input
                                    // of the node
                                    newEdge =
                                            addExchangeAndReconnectEdge(
                                                    tableConfig, edge, inputProperty, false, true);
                                    updateOriginalEdgeInMultipleInput(
                                            node, i, (BatchExecExchange) newEdge.getSource());
                                }
                                // update the edge
                                newEdges.set(i, newEdge);
                                changed = true;
                            } else if (hasSortInputForInputSortedNode(node)) {
                                // if operation chaining is disabled, this could mark sure the sort
                                // node and its output can also be connected by ForwardPartitioner
                                ExecEdge newEdge =
                                        addExchangeAndReconnectEdge(
                                                tableConfig, edge, inputProperty, true, true);
                                newEdges.set(i, newEdge);
                                changed = true;
                            }
                        }
                        if (changed) {
                            node.setInputEdges(newEdges);
                        }
                    }
                };
        execGraph.getRootNodes().forEach(s -> s.accept(visitor));
        return execGraph;
    }

@Override
    public ContextResolvedModel deserialize(JsonParser jsonParser, DeserializationContext ctx)
            throws IOException {
        final TableConfigOptions.CatalogPlanRestore planRestoreOption =
                SerdeContext.get(ctx).getConfiguration().get(PLAN_RESTORE_CATALOG_OBJECTS);
        final CatalogManager catalogManager =
                SerdeContext.get(ctx).getFlinkContext().getCatalogManager();
        final ObjectNode objectNode = jsonParser.readValueAsTree();

        final ObjectIdentifier identifier =
                ctx.readValue(
                        traverse(objectNode.required(FIELD_NAME_IDENTIFIER), jsonParser.getCodec()),
                        ObjectIdentifier.class);
        final @Nullable ResolvedCatalogModel restoredModel =
                deserializeOptionalField(
                                objectNode,
                                FIELD_NAME_CATALOG_MODEL,
                                ResolvedCatalogModel.class,
                                jsonParser.getCodec(),
                                ctx)
                        .orElse(null);

        final Optional<ContextResolvedModel> contextResolvedModelFromCatalog =
                catalogManager.getModel(identifier);

        // If plan has no catalog model field or no options field,
        // the model is permanent in the catalog and the option is plan all enforced, then fail
        if ((objectNode.at(optionsPointer).isMissingNode()
                && isPlanEnforced(planRestoreOption)
                && contextResolvedModelFromCatalog
                        .map(ContextResolvedModel::isPermanent)
                        .orElse(false))) {
            throw lookupDisabled(identifier);
        }

        // If we have a schema from the plan and from the catalog, we need to check they match.
        if (restoredModel != null && contextResolvedModelFromCatalog.isPresent()) {
            ContextResolvedModel modelFromCatalog = contextResolvedModelFromCatalog.get();
            if (!areColumnsEqual(
                    restoredModel.getResolvedInputSchema(),
                    modelFromCatalog.getResolvedModel().getResolvedInputSchema())) {
                throw schemaNotMatching(
                        identifier,
                        "input schema",
                        restoredModel.getResolvedInputSchema(),
                        modelFromCatalog.getResolvedModel().getResolvedInputSchema());
            }
            if (!areColumnsEqual(
                    restoredModel.getResolvedOutputSchema(),
                    modelFromCatalog.getResolvedModel().getResolvedOutputSchema())) {
                throw schemaNotMatching(
                        identifier,
                        "output schema",
                        restoredModel.getResolvedInputSchema(),
                        modelFromCatalog.getResolvedModel().getResolvedInputSchema());
            }
        }

        if (restoredModel == null || isLookupForced(planRestoreOption)) {
            return contextResolvedModelFromCatalog.orElseThrow(
                    () -> missingModelFromCatalog(identifier, isLookupForced(planRestoreOption)));
        }

        if (contextResolvedModelFromCatalog.isPresent()) {
            // If no config map is present, then the ContextResolvedModel was serialized with
            // SCHEMA, so we just need to return the catalog query result
            if (objectNode.at(optionsPointer).isMissingNode()) {
                return contextResolvedModelFromCatalog.get();
            }

            return contextResolvedModelFromCatalog
                    .flatMap(ContextResolvedModel::getCatalog)
                    .map(c -> ContextResolvedModel.permanent(identifier, c, restoredModel))
                    .orElseGet(() -> ContextResolvedModel.temporary(identifier, restoredModel));
        }

        return ContextResolvedModel.temporary(identifier, restoredModel);
    }

