public static DataViewSpec[] extractDataViewSpecs(int index, DataType accType) {
        if (!(accType instanceof FieldsDataType)) {
            return new DataViewSpec[0];
        }
        FieldsDataType compositeAccType = (FieldsDataType) accType;
        if (includesDataView(compositeAccType)) {
            LogicalType logicalType = compositeAccType.getLogicalType();
            if (logicalType instanceof RowType) {
                List<DataType> childrenDataTypes = compositeAccType.getChildren();
                return IntStream.range(0, childrenDataTypes.size())
                        .mapToObj(
                                i -> {
                                    DataType childDataType = childrenDataTypes.get(i);
                                    LogicalType childLogicalType = childDataType.getLogicalType();
                                    if ((childLogicalType instanceof RowType)
                                            && includesDataView((FieldsDataType) childDataType)) {
                                        throw new TableException(
                                                "For Python AggregateFunction, DataView cannot be used in the"
                                                        + " nested columns of the accumulator. ");
                                    } else if ((childLogicalType instanceof StructuredType)
                                            && ListView.class.isAssignableFrom(
                                                    ((StructuredType) childLogicalType)
                                                            .getImplementationClass()
                                                            .get())) {
                                        return new ListViewSpec(
                                                "agg"
                                                        + index
                                                        + "$"
                                                        + ((RowType) logicalType)
                                                                .getFieldNames()
                                                                .get(i),
                                                i,
                                                childDataType.getChildren().get(0));
                                    } else if ((childLogicalType instanceof StructuredType)
                                            && MapView.class.isAssignableFrom(
                                                    ((StructuredType) childLogicalType)
                                                            .getImplementationClass()
                                                            .get())) {
                                        return new MapViewSpec(
                                                "agg"
                                                        + index
                                                        + "$"
                                                        + ((RowType) logicalType)
                                                                .getFieldNames()
                                                                .get(i),
                                                i,
                                                childDataType.getChildren().get(0),
                                                false);
                                    }
                                    return null;
                                })
                        .filter(Objects::nonNull)
                        .toArray(DataViewSpec[]::new);
            } else {
                throw new TableException(
                        "For Python AggregateFunction you can only use DataView in " + "Row type.");
            }
        } else {
            return new DataViewSpec[0];
        }
    }

public StreamPhysicalRel visit(
            final StreamPhysicalRel rel, final ImmutableBitSet requireDeterminism) {
        if (rel instanceof StreamPhysicalSink) {
            return visitSink((StreamPhysicalSink) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalLegacySink<?>) {
            return visitLegacySink((StreamPhysicalLegacySink<?>) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalCalcBase) {
            return visitCalc((StreamPhysicalCalcBase) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalCorrelateBase) {
            return visitCorrelate((StreamPhysicalCorrelateBase) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalLookupJoin) {
            return visitLookupJoin((StreamPhysicalLookupJoin) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalTableSourceScan) {
            return visitTableSourceScan((StreamPhysicalTableSourceScan) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalLegacyTableSourceScan
                || rel instanceof StreamPhysicalDataStreamScan
                || rel instanceof StreamPhysicalValues) {
            // not cdc source, end visit
            return rel;
        } else if (rel instanceof StreamPhysicalGroupAggregateBase) {
            return visitGroupAggregate((StreamPhysicalGroupAggregateBase) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalWindowAggregateBase) {
            return visitWindowAggregate(
                    (StreamPhysicalWindowAggregateBase) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalExpand) {
            return visitExpand((StreamPhysicalExpand) rel, requireDeterminism);
        } else if (rel instanceof CommonPhysicalJoin) {
            return visitJoin((CommonPhysicalJoin) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalMultiJoin) {
            return visitMultiJoin((StreamPhysicalMultiJoin) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalOverAggregateBase) {
            return visitOverAggregate((StreamPhysicalOverAggregateBase) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalRank) {
            return visitRank((StreamPhysicalRank) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalWindowDeduplicate) {
            return visitWindowDeduplicate(
                    (StreamPhysicalWindowDeduplicate) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalWindowRank) {
            return visitWindowRank((StreamPhysicalWindowRank) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalWindowTableFunction) {
            return visitWindowTableFunction(
                    (StreamPhysicalWindowTableFunction) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalDeltaJoin) {
            return visitDeltaJoin((StreamPhysicalDeltaJoin) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalMLPredictTableFunction) {
            return visitMLPredictTableFunction(
                    (StreamPhysicalMLPredictTableFunction) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalChangelogNormalize) {
            return visitChangelogNormalize(
                    (StreamPhysicalChangelogNormalize) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalDropUpdateBefore
                || rel instanceof StreamPhysicalMiniBatchAssigner
                || rel instanceof StreamPhysicalUnion
                || rel instanceof StreamPhysicalSort
                || rel instanceof StreamPhysicalLimit
                || rel instanceof StreamPhysicalSortLimit
                || rel instanceof StreamPhysicalTemporalSort
                || rel instanceof StreamPhysicalWatermarkAssigner
                || rel instanceof StreamPhysicalExchange) {
            // transit requireDeterminism transparently
            return transmitDeterminismRequirement(rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalMatch) {
            return visitMatch((StreamPhysicalMatch) rel, requireDeterminism);
        } else if (rel instanceof StreamPhysicalProcessTableFunction) {
            return visitPtf((StreamPhysicalProcessTableFunction) rel, requireDeterminism);
        } else {
            throw new UnsupportedOperationException(
                    String.format(
                            "Unsupported to visit node %s, please add the visit implementation if it is a newly added stream physical node.",
                            rel.getClass().getSimpleName()));
        }
    }

public List<RelNode> reuseDuplicatedScan(List<RelNode> relNodes) {
        ReusableScanVisitor visitor = new ReusableScanVisitor();
        relNodes.forEach(visitor::go);

        for (List<CommonPhysicalTableSourceScan> reusableNodes :
                visitor.digestToReusableScans().values()) {
            if (reusableNodes.size() < 2 || reusableWithoutAdjust(reusableNodes)) {
                continue;
            }

            if (reusableNodes.stream()
                    .anyMatch(ScanReuserUtils::containsRexNodeSpecAfterProjection)) {
                continue;
            }

            CommonPhysicalTableSourceScan pickScan = pickScanWithWatermark(reusableNodes);
            TableSourceTable pickTable = pickScan.tableSourceTable();
            RexBuilder rexBuilder = pickScan.getCluster().getRexBuilder();

            // 1. Find union fields.
            // Input scan schema: physical projection fields + metadata fields.
            // (See DynamicSourceUtils.validateAndApplyMetadata)
            // So It is safe to collect physical projection fields + metadata fields.
            TreeSet<int[]> allProjectFieldSet = new TreeSet<>(INT_ARRAY_COMPARATOR);
            Set<String> allMetaKeySet = new HashSet<>();
            for (CommonPhysicalTableSourceScan scan : reusableNodes) {
                TableSourceTable source = scan.tableSourceTable();
                allProjectFieldSet.addAll(Arrays.asList(projectedFields(source)));
                allMetaKeySet.addAll(metadataKeys(source));
            }

            int[][] allProjectFields = allProjectFieldSet.toArray(new int[0][]);
            List<String> allMetaKeys =
                    enforceMetadataKeyOrder(allMetaKeySet, pickTable.tableSource());

            // 2. Create new source.
            List<SourceAbilitySpec> specs = abilitySpecsWithoutEscaped(pickTable);

            // 2.1 Create produced type.
            // The source produced type is the input type into the runtime. The format looks as:
            // PHYSICAL COLUMNS + METADATA COLUMNS. While re-compute the source ability specs with
            // source metadata, we need to distinguish between schema type and produced type, which
            // source ability specs use produced type instead of schema type.
            RowType originType =
                    DynamicSourceUtils.createProducedType(
                            pickTable.contextResolvedTable().getResolvedSchema(),
                            pickTable.tableSource());

            // 2.2 Apply projections
            List<SourceAbilitySpec> newSpecs = new ArrayList<>();
            RowType newSourceType =
                    applyPhysicalAndMetadataPushDown(
                            pickTable.tableSource(),
                            originType,
                            newSpecs,
                            concatProjectedFields(
                                    pickTable.contextResolvedTable().getResolvedSchema(),
                                    originType,
                                    allProjectFields,
                                    allMetaKeys),
                            allProjectFields,
                            allMetaKeys);
            specs.addAll(newSpecs);

            // 2.3 Watermark spec
            Optional<WatermarkPushDownSpec> watermarkSpec =
                    getAdjustedWatermarkSpec(pickTable, originType, newSourceType);
            if (watermarkSpec.isPresent()) {
                specs.add(watermarkSpec.get());
                newSourceType = watermarkSpec.get().getProducedType().get();
            }

            // 2.4 Create a new ScanTableSource. ScanTableSource can not be pushed down twice.
            DynamicTableSourceSpec tableSourceSpec =
                    new DynamicTableSourceSpec(pickTable.contextResolvedTable(), specs);
            ScanTableSource newTableSource =
                    tableSourceSpec.getScanTableSource(flinkContext, flinkTypeFactory);

            TableSourceTable newSourceTable =
                    pickTable.replace(
                            newTableSource,
                            ((FlinkTypeFactory) rexBuilder.getTypeFactory())
                                    .buildRelNodeRowType(newSourceType),
                            specs.toArray(new SourceAbilitySpec[0]));

            RelNode newScan = pickScan.copy(newSourceTable);

            // 3. Create projects.
            for (CommonPhysicalTableSourceScan scan : reusableNodes) {
                TableSourceTable source = scan.tableSourceTable();
                int[][] projectedFields = projectedFields(source);
                List<String> metaKeys = metadataKeys(source);

                // Don't need add calc
                if (Arrays.deepEquals(projectedFields, allProjectFields)
                        && metaKeys.equals(allMetaKeys)) {
                    // full project may be pushed into source, update to the new source
                    replaceMap.put(scan, newScan);
                    continue;
                }

                RexProgramBuilder builder = new RexProgramBuilder(newScan.getRowType(), rexBuilder);

                for (int[] field : projectedFields) {
                    int index = indexOf(allProjectFields, field);
                    builder.addProject(index, newScan.getRowType().getFieldNames().get(index));
                }

                for (String key : metaKeys) {
                    int index = allProjectFields.length + allMetaKeys.indexOf(key);
                    builder.addProject(index, newScan.getRowType().getFieldNames().get(index));
                }

                replaceMap.put(scan, createCalcForScan(newScan, builder.getProgram()));
            }
        }

        ReplaceScanWithCalcShuttle replaceShuttle = new ReplaceScanWithCalcShuttle(replaceMap);
        return relNodes.stream()
                .map(rel -> rel.accept(replaceShuttle))
                .collect(Collectors.toList());
    }

