static List<RankProcessStrategy> analyzeRankProcessStrategies(
            StreamPhysicalRel rank, ImmutableBitSet partitionKey, RelCollation orderKey) {

        FlinkRelMetadataQuery mq = (FlinkRelMetadataQuery) rank.getCluster().getMetadataQuery();
        List<RelFieldCollation> fieldCollations = orderKey.getFieldCollations();
        boolean isUpdateStream = !ChangelogPlanUtils.inputInsertOnly(rank);
        RelNode input = rank.getInput(0);

        if (isUpdateStream) {
            Set<ImmutableBitSet> upsertKeys =
                    mq.getUpsertKeysInKeyGroupRange(input, partitionKey.toArray());
            if (upsertKeys == null
                    || upsertKeys.isEmpty()
                    // upsert key should contains partition key
                    || upsertKeys.stream().noneMatch(k -> k.contains(partitionKey))) {
                // and we fall back to using retract rank
                return Collections.singletonList(RETRACT_STRATEGY);
            } else {
                FlinkRelMetadataQuery fmq = FlinkRelMetadataQuery.reuseOrCreate(mq);
                RelModifiedMonotonicity monotonicity = fmq.getRelModifiedMonotonicity(input);
                boolean isMonotonic = false;
                if (monotonicity != null && !fieldCollations.isEmpty()) {
                    isMonotonic =
                            fieldCollations.stream()
                                    .allMatch(
                                            collation -> {
                                                SqlMonotonicity fieldMonotonicity =
                                                        monotonicity
                                                                .fieldMonotonicities()[
                                                                collation.getFieldIndex()];
                                                RelFieldCollation.Direction direction =
                                                        collation.direction;
                                                if ((fieldMonotonicity == SqlMonotonicity.DECREASING
                                                                || fieldMonotonicity
                                                                        == SqlMonotonicity
                                                                                .STRICTLY_DECREASING)
                                                        && direction
                                                                == RelFieldCollation.Direction
                                                                        .ASCENDING) {
                                                    // sort field is ascending and its monotonicity
                                                    // is decreasing
                                                    return true;
                                                } else if ((fieldMonotonicity
                                                                        == SqlMonotonicity
                                                                                .INCREASING
                                                                || fieldMonotonicity
                                                                        == SqlMonotonicity
                                                                                .STRICTLY_INCREASING)
                                                        && direction
                                                                == RelFieldCollation.Direction
                                                                        .DESCENDING) {
                                                    // sort field is descending and its monotonicity
                                                    // is increasing
                                                    return true;
                                                } else {
                                                    // sort key is a grouping key of upstream agg,
                                                    // it is monotonic
                                                    return fieldMonotonicity
                                                            == SqlMonotonicity.CONSTANT;
                                                }
                                            });
                }

                if (isMonotonic) {
                    // TODO: choose a set of primary key
                    return Arrays.asList(
                            new UpdateFastStrategy(upsertKeys.iterator().next().toArray()),
                            RETRACT_STRATEGY);
                } else {
                    return Collections.singletonList(RETRACT_STRATEGY);
                }
            }
        } else {
            return Collections.singletonList(APPEND_FAST_STRATEGY);
        }
    }

public static Object toFlinkInternalValue(Comparable<?> value, LogicalType valueType) {
        if (value == null) {
            return null;
        }
        switch (valueType.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                if (value instanceof NlsString) {
                    return BinaryStringData.fromString(((NlsString) value).getValue());
                }
                if (value instanceof String) {
                    return BinaryStringData.fromString((String) value);
                }
                break;
            case BOOLEAN:
                if (value instanceof Boolean) {
                    return value;
                }
                break;
            case BINARY:
            case VARBINARY:
                if (value instanceof ByteString) {
                    return ((ByteString) value).getBytes();
                }
                break;
            case UUID:
                if (value instanceof java.util.UUID) {
                    return UuidUtils.toBytes((java.util.UUID) value);
                }
                break;
            case DECIMAL:
                if (value instanceof BigDecimal) {
                    return DecimalData.fromBigDecimal(
                            (BigDecimal) value,
                            LogicalTypeChecks.getPrecision(valueType),
                            LogicalTypeChecks.getScale(valueType));
                }
                break;
            case TINYINT:
                if (value instanceof Number) {
                    return ((Number) value).byteValue();
                }
                break;
            case SMALLINT:
                if (value instanceof Number) {
                    return ((Number) value).shortValue();
                }
                break;
            case INTEGER:
            case INTERVAL_YEAR_MONTH:
                if (value instanceof Number) {
                    return ((Number) value).intValue();
                }
                break;
            case BIGINT:
            case INTERVAL_DAY_TIME:
                if (value instanceof Number) {
                    return ((Number) value).longValue();
                }
                break;
            case FLOAT:
                if (value instanceof Number) {
                    return ((Number) value).floatValue();
                }
                break;
            case DOUBLE:
                if (value instanceof Number) {
                    return ((Number) value).doubleValue();
                }
                break;
            case DATE:
                if (value instanceof DateString) {
                    return ((DateString) value).getDaysSinceEpoch();
                }
                if (value instanceof Number) {
                    return ((Number) value).intValue();
                }
                break;
            case TIME_WITHOUT_TIME_ZONE:
                if (value instanceof TimeString) {
                    return ((TimeString) value).getMillisOfDay();
                }
                if (value instanceof Number) {
                    return ((Number) value).intValue();
                }
                break;
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                if (value instanceof TimestampString) {
                    return TimestampData.fromLocalDateTime(
                            toLocalDateTime((TimestampString) value));
                }
                break;
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                if (value instanceof TimestampString) {
                    return TimestampData.fromInstant(
                            toLocalDateTime((TimestampString) value)
                                    .atOffset(ZoneOffset.UTC)
                                    .toInstant());
                }
                break;
            case DISTINCT_TYPE:
                return toFlinkInternalValue(value, ((DistinctType) valueType).getSourceType());
            case SYMBOL:
                if (value instanceof Enum) {
                    return value;
                }
                break;
            case TIMESTAMP_WITH_TIME_ZONE:
            case ARRAY:
            case MULTISET:
            case MAP:
            case ROW:
            case STRUCTURED_TYPE:
            case NULL:
            case UNRESOLVED:
            case DESCRIPTOR:
                throw new CodeGenException("Type not supported: " + valueType);
        }
        throw new IllegalStateException(
                "Unexpected class " + value.getClass() + " for value of type " + valueType);
    }

public static GroupWindowAssigner<TimeWindow> createWindowAssigner(
            TimeAttributeWindowingStrategy windowingStrategy) {
        WindowSpec windowSpec = windowingStrategy.getWindow();
        boolean isProctime = windowingStrategy.isProctime();
        if (windowSpec instanceof TumblingWindowSpec) {
            TumblingWindowSpec tumblingWindowSpec = (TumblingWindowSpec) windowSpec;
            TumblingWindowAssigner windowAssigner =
                    TumblingWindowAssigner.of(tumblingWindowSpec.getSize());
            if (isProctime) {
                windowAssigner = windowAssigner.withProcessingTime();
            }
            if (tumblingWindowSpec.getOffset() != null) {
                windowAssigner = windowAssigner.withOffset(tumblingWindowSpec.getOffset());
            }
            return windowAssigner;
        } else if (windowSpec instanceof HoppingWindowSpec) {
            HoppingWindowSpec hoppingWindowSpec = (HoppingWindowSpec) windowSpec;
            SlidingWindowAssigner windowAssigner =
                    SlidingWindowAssigner.of(
                            hoppingWindowSpec.getSize(), hoppingWindowSpec.getSlide());
            if (isProctime) {
                windowAssigner = windowAssigner.withProcessingTime();
            }
            if (hoppingWindowSpec.getOffset() != null) {
                windowAssigner = windowAssigner.withOffset(hoppingWindowSpec.getOffset());
            }
            return windowAssigner;
        } else if (windowSpec instanceof CumulativeWindowSpec) {
            CumulativeWindowSpec cumulativeWindowSpec = (CumulativeWindowSpec) windowSpec;
            CumulativeWindowAssigner windowAssigner =
                    CumulativeWindowAssigner.of(
                            cumulativeWindowSpec.getMaxSize(), cumulativeWindowSpec.getStep());
            if (isProctime) {
                windowAssigner = windowAssigner.withProcessingTime();
            }
            if (cumulativeWindowSpec.getOffset() != null) {
                windowAssigner = windowAssigner.withOffset(cumulativeWindowSpec.getOffset());
            }
            return windowAssigner;
        } else if (windowSpec instanceof SessionWindowSpec) {
            SessionWindowSpec sessionWindowSpec = (SessionWindowSpec) windowSpec;
            SessionWindowAssigner windowAssigner =
                    SessionWindowAssigner.withGap(sessionWindowSpec.getGap());
            if (isProctime) {
                windowAssigner = windowAssigner.withProcessingTime();
            }
            return windowAssigner;
        } else {
            throw new TableException(
                    String.format(
                            "Unknown window spec: %s", windowSpec.getClass().getSimpleName()));
        }
    }

public static List<TableChange> validateAndExtractColumnChanges(
            ResolvedSchema oldSchema, ResolvedSchema newSchema, boolean schemaDefinedInQuery) {
        final List<Column> oldColumns = oldSchema.getColumns();
        final List<Column> newColumns = newSchema.getColumns();
        final Set<String> newColumnNames =
                newColumns.stream().map(Column::getName).collect(Collectors.toSet());
        // Position each old column among the columns that survive into the new schema, so retained
        // non-persisted columns (absent from the query projection) do not skew the position diff.
        final Map<String, Tuple2<Column, Integer>> oldByName = new HashMap<>();
        int nextPosition = 0;
        for (final Column oldColumn : oldColumns) {
            final Integer position =
                    newColumnNames.contains(oldColumn.getName()) ? nextPosition++ : null;
            oldByName.put(oldColumn.getName(), Tuple2.of(oldColumn, position));
        }
        final Set<String> seen = new HashSet<>();
        final List<TableChange> changes = new ArrayList<>();
        for (int newIndex = 0; newIndex < newColumns.size(); newIndex++) {
            final Column newColumn = newColumns.get(newIndex);
            seen.add(newColumn.getName());
            final Tuple2<Column, Integer> oldEntry = oldByName.get(newColumn.getName());
            if (oldEntry == null) {
                changes.add(addChange(newColumn, schemaDefinedInQuery));
                continue;
            }
            final Column oldColumn = oldEntry.f0;
            // The query order is authoritative, so reposition a column the query moved; a
            // DDL-defined schema keeps the arbitrary DDL order.
            if (!schemaDefinedInQuery) {
                applyPositionChanges(newColumns, oldEntry, newIndex, changes);
            }
            if (oldColumn.isPhysical()
                    && newColumn.isPhysical()
                    && typeChanged(oldColumn, newColumn, schemaDefinedInQuery)) {
                final DataType newType =
                        schemaDefinedInQuery
                                ? newColumn.getDataType()
                                : newColumn.getDataType().nullable();
                changes.add(TableChange.modifyPhysicalColumnType(oldColumn, newType));
                // Type changed; still check whether the comment also changed.
                final String oldComment = oldColumn.getComment().orElse(null);
                final String newComment = newColumn.getComment().orElse(null);
                if (!Objects.equals(oldComment, newComment)) {
                    changes.add(TableChange.modifyColumnComment(oldColumn, newComment));
                }
                continue;
            }
            if (oldColumn.getClass() != newColumn.getClass()
                    || !definitionEquals(oldColumn, newColumn)) {
                changes.add(
                        new TableChange.ModifyColumn(
                                oldColumn,
                                normalizedColumn(newColumn, schemaDefinedInQuery),
                                null));
                continue;
            }
            final String oldComment = oldColumn.getComment().orElse(null);
            final String newComment = newColumn.getComment().orElse(null);
            if (!Objects.equals(oldComment, newComment)) {
                changes.add(TableChange.modifyColumnComment(oldColumn, newComment));
            }
        }

        for (Map.Entry<String, Tuple2<Column, Integer>> entry : oldByName.entrySet()) {
            if (seen.contains(entry.getKey())) {
                continue;
            }
            // Without an explicit DDL column list the new schema only reflects the query
            // projection, so old non-persisted columns are retained, not dropped.
            if (!schemaDefinedInQuery && !entry.getValue().f0.isPersisted()) {
                continue;
            }
            changes.add(TableChange.dropColumn(entry.getKey()));
        }
        return changes;
    }

public static DataFormatConverter getConverterForDataType(DataType originDataType) {
        DataType dataType = originDataType.nullable();
        DataFormatConverter converter = TYPE_TO_CONVERTER.get(dataType);
        if (converter != null) {
            return converter;
        }

        Class<?> clazz = dataType.getConversionClass();
        LogicalType logicalType = dataType.getLogicalType();
        switch (logicalType.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                if (clazz == String.class) {
                    return StringConverter.INSTANCE;
                } else if (clazz == StringData.class) {
                    return StringDataConverter.INSTANCE;
                } else {
                    throw new RuntimeException("Not support class for VARCHAR: " + clazz);
                }
            case BINARY:
            case VARBINARY:
                return PrimitiveByteArrayConverter.INSTANCE;
            case DECIMAL:
                Tuple2<Integer, Integer> ps = getPrecision(logicalType);
                if (clazz == BigDecimal.class) {
                    return new BigDecimalConverter(ps.f0, ps.f1);
                } else if (clazz == DecimalData.class) {
                    return new DecimalDataConverter(ps.f0, ps.f1);
                } else {
                    throw new RuntimeException(
                            "Not support conversion class for DECIMAL: " + clazz);
                }
            case TIMESTAMP_WITHOUT_TIME_ZONE:
                int precisionOfTS = getDateTimePrecision(logicalType);
                if (clazz == Timestamp.class) {
                    return new TimestampConverter(precisionOfTS);
                } else if (clazz == LocalDateTime.class) {
                    return new LocalDateTimeConverter(precisionOfTS);
                } else if (clazz == TimestampData.class) {
                    return new TimestampDataConverter(precisionOfTS);
                } else {
                    throw new RuntimeException(
                            "Not support conversion class for TIMESTAMP WITHOUT TIME ZONE: "
                                    + clazz);
                }
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                int precisionOfLZTS = getDateTimePrecision(logicalType);
                if (clazz == Instant.class) {
                    return new InstantConverter(precisionOfLZTS);
                } else if (clazz == Long.class || clazz == long.class) {
                    return new LongTimestampDataConverter(precisionOfLZTS);
                } else if (clazz == TimestampData.class) {
                    return new TimestampDataConverter(precisionOfLZTS);
                } else if (clazz == Timestamp.class) {
                    return new TimestampLtzConverter(precisionOfLZTS);
                } else {
                    throw new RuntimeException(
                            "Not support conversion class for TIMESTAMP WITH LOCAL TIME ZONE: "
                                    + clazz);
                }
            case ARRAY:
                if (clazz == ArrayData.class) {
                    return ArrayDataConverter.INSTANCE;
                } else if (clazz == boolean[].class) {
                    return PrimitiveBooleanArrayConverter.INSTANCE;
                } else if (clazz == short[].class) {
                    return PrimitiveShortArrayConverter.INSTANCE;
                } else if (clazz == int[].class) {
                    return PrimitiveIntArrayConverter.INSTANCE;
                } else if (clazz == long[].class) {
                    return PrimitiveLongArrayConverter.INSTANCE;
                } else if (clazz == float[].class) {
                    return PrimitiveFloatArrayConverter.INSTANCE;
                } else if (clazz == double[].class) {
                    return PrimitiveDoubleArrayConverter.INSTANCE;
                }
                if (dataType instanceof CollectionDataType) {
                    return new ObjectArrayConverter(
                            ((CollectionDataType) dataType)
                                    .getElementDataType()
                                    .bridgedTo(clazz.getComponentType()));
                } else {
                    BasicArrayTypeInfo typeInfo =
                            (BasicArrayTypeInfo)
                                    ((LegacyTypeInformationType) dataType.getLogicalType())
                                            .getTypeInformation();
                    return new ObjectArrayConverter(
                            fromLegacyInfoToDataType(typeInfo.getComponentInfo())
                                    .bridgedTo(clazz.getComponentType()));
                }
            case MAP:
                if (clazz == MapData.class) {
                    return MapDataConverter.INSTANCE;
                }
                KeyValueDataType keyValueDataType = (KeyValueDataType) dataType;
                return new MapConverter(
                        keyValueDataType.getKeyDataType(), keyValueDataType.getValueDataType());
            case MULTISET:
                if (clazz == MapData.class) {
                    return MapDataConverter.INSTANCE;
                }
                CollectionDataType collectionDataType = (CollectionDataType) dataType;
                return new MapConverter(
                        collectionDataType.getElementDataType(),
                        DataTypes.INT().bridgedTo(Integer.class));
            case ROW:
            case STRUCTURED_TYPE:
                TypeInformation<?> asTypeInfo = fromDataTypeToTypeInfo(dataType);
                if (asTypeInfo instanceof InternalTypeInfo && clazz == RowData.class) {
                    LogicalType realLogicalType =
                            ((InternalTypeInfo<?>) asTypeInfo).toLogicalType();
                    return new RowDataConverter(getFieldCount(realLogicalType));
                }

                // legacy

                CompositeType compositeType = (CompositeType) asTypeInfo;
                DataType[] fieldTypes =
                        Stream.iterate(0, x -> x + 1)
                                .limit(compositeType.getArity())
                                .map((Function<Integer, TypeInformation>) compositeType::getTypeAt)
                                .map(TypeConversions::fromLegacyInfoToDataType)
                                .toArray(DataType[]::new);
                if (clazz == RowData.class) {
                    return new RowDataConverter(compositeType.getArity());
                } else if (clazz == Row.class) {
                    return new RowConverter(fieldTypes);
                } else if (Tuple.class.isAssignableFrom(clazz)) {
                    return new TupleConverter((Class<Tuple>) clazz, fieldTypes);
                } else if (CaseClassConverter.PRODUCT_CLASS != null
                        && CaseClassConverter.PRODUCT_CLASS.isAssignableFrom(clazz)) {
                    return new CaseClassConverter((TupleTypeInfoBase) compositeType, fieldTypes);
                } else if (compositeType instanceof PojoTypeInfo) {
                    return new PojoConverter((PojoTypeInfo) compositeType, fieldTypes);
                } else {
                    throw new IllegalStateException(
                            "Cannot find a converter for type "
                                    + compositeType
                                    + ". If the target should be a converter to scala.Product, then you might have a scala classpath issue.");
                }
            case RAW:
                if (logicalType instanceof RawType) {
                    final RawType<?> rawType = (RawType<?>) logicalType;
                    if (clazz == RawValueData.class) {
                        return RawValueDataConverter.INSTANCE;
                    } else {
                        return new GenericConverter<>(rawType.getTypeSerializer());
                    }
                }

                // legacy

                TypeInformation typeInfo =
                        logicalType instanceof LegacyTypeInformationType
                                ? ((LegacyTypeInformationType) logicalType).getTypeInformation()
                                : ((TypeInformationRawType) logicalType).getTypeInformation();

                // planner type info
                if (typeInfo instanceof StringDataTypeInfo) {
                    return StringDataConverter.INSTANCE;
                } else if (typeInfo instanceof DecimalDataTypeInfo) {
                    DecimalDataTypeInfo decimalType = (DecimalDataTypeInfo) typeInfo;
                    return new DecimalDataConverter(decimalType.precision(), decimalType.scale());
                } else if (typeInfo instanceof BigDecimalTypeInfo) {
                    BigDecimalTypeInfo decimalType = (BigDecimalTypeInfo) typeInfo;
                    return new BigDecimalConverter(decimalType.precision(), decimalType.scale());
                } else if (typeInfo instanceof TimestampDataTypeInfo) {
                    TimestampDataTypeInfo timestampDataTypeInfo = (TimestampDataTypeInfo) typeInfo;
                    return new TimestampDataConverter(timestampDataTypeInfo.getPrecision());
                } else if (typeInfo instanceof LegacyLocalDateTimeTypeInfo) {
                    LegacyLocalDateTimeTypeInfo dateTimeType =
                            (LegacyLocalDateTimeTypeInfo) typeInfo;
                    return new LocalDateTimeConverter(dateTimeType.getPrecision());
                } else if (typeInfo instanceof LegacyTimestampTypeInfo) {
                    LegacyTimestampTypeInfo timestampType = (LegacyTimestampTypeInfo) typeInfo;
                    return new TimestampConverter(timestampType.getPrecision());
                } else if (typeInfo instanceof LegacyInstantTypeInfo) {
                    LegacyInstantTypeInfo instantTypeInfo = (LegacyInstantTypeInfo) typeInfo;
                    return new InstantConverter(instantTypeInfo.getPrecision());
                }

                if (clazz == RawValueData.class) {
                    return RawValueDataConverter.INSTANCE;
                } else if (clazz == Variant.class) {
                    return VariantConverter.INSTANCE;
                }

                return new GenericConverter(typeInfo.createSerializer(new SerializerConfigImpl()));
            default:
                throw new RuntimeException("Not support dataType: " + dataType);
        }
    }

@Override
    public void finishBundle(Map<RowData, List<RowData>> buffer, Collector<RowData> out)
            throws Exception {
        for (Map.Entry<RowData, List<RowData>> entry : buffer.entrySet()) {
            RowData currentKey = entry.getKey();
            List<RowData> inputRows = entry.getValue();

            boolean firstRow = false;

            // step 1: get the accumulator for the current key

            // set current key to access state under the key
            ctx.setCurrentKey(currentKey);
            RowData acc = accState.value();
            if (acc == null) {
                // Don't create a new accumulator for a retraction message. This
                // might happen if the retraction message is the first message for the
                // key or after a state clean up.
                Iterator<RowData> inputIter = inputRows.iterator();
                while (inputIter.hasNext()) {
                    RowData current = inputIter.next();
                    if (isRetractMsg(current)) {
                        inputIter.remove(); // remove all the beginning retraction messages
                    } else {
                        break;
                    }
                }
                if (inputRows.isEmpty()) {
                    // Skip this key and continue processing other keys in the bundle.
                    // Using 'return' here would incorrectly exit the entire method,
                    // silently dropping all remaining keys in the bundle.
                    continue;
                }
                acc = function.createAccumulators();
                firstRow = true;
            }

            // step 2: accumulate
            function.setAccumulators(acc);

            // get previous aggregate result
            RowData prevAggValue = function.getValue();

            for (RowData input : inputRows) {
                if (isAccumulateMsg(input)) {
                    function.accumulate(input);
                } else {
                    function.retract(input);
                }
            }

            // get current aggregate result
            RowData newAggValue = function.getValue();

            // get updated accumulator
            acc = function.getAccumulators();

            if (!recordCounter.recordCountIsZero(acc)) {
                // we aggregated at least one record for this key

                // update acc to state
                accState.update(acc);

                // if this was not the first row and we have to emit retractions
                if (!firstRow) {
                    if (stateRetentionTime > 0 || !equaliser.equals(prevAggValue, newAggValue)) {
                        // new row is not same with prev row
                        if (generateUpdateBefore) {
                            // prepare UPDATE_BEFORE message for previous row
                            resultRow
                                    .replace(currentKey, prevAggValue)
                                    .setRowKind(RowKind.UPDATE_BEFORE);
                            out.collect(resultRow);
                        }
                        // prepare UPDATE_AFTER message for new row
                        resultRow.replace(currentKey, newAggValue).setRowKind(RowKind.UPDATE_AFTER);
                        out.collect(resultRow);
                    }
                    // new row is same with prev row, no need to output
                } else {
                    // this is the first, output new result
                    // prepare INSERT message for new row
                    resultRow.replace(currentKey, newAggValue).setRowKind(RowKind.INSERT);
                    out.collect(resultRow);
                }

            } else {
                // we retracted the last record for this key
                // if this is not first row sent out a DELETE message
                if (!firstRow) {
                    // prepare DELETE message for previous row
                    resultRow.replace(currentKey, prevAggValue).setRowKind(RowKind.DELETE);
                    out.collect(resultRow);
                }
                // and clear all state
                accState.clear();
                // cleanup dataview under current key
                function.cleanup();
            }
        }
    }

