@Override
    protected void tryOptimizeAdaptiveJoin(
            OperatorsFinished operatorsFinished,
            StreamGraphContext context,
            ImmutableStreamNode adaptiveJoinNode,
            List<ImmutableStreamEdge> upstreamStreamEdges,
            AdaptiveJoin adaptiveJoin) {
        if (!canPerformOptimization(adaptiveJoinNode, context)
                || optimizedAdaptiveJoinNodes.contains(adaptiveJoinNode.getId())) {
            return;
        }
        for (ImmutableStreamEdge upstreamEdge : upstreamStreamEdges) {
            IntermediateDataSetID relatedDataSetId =
                    context.getConsumedIntermediateDataSetId(upstreamEdge.getEdgeId());
            long producedBytes =
                    operatorsFinished.getResultInfoMap().get(upstreamEdge.getSourceId()).stream()
                            .filter(
                                    blockingResultInfo ->
                                            relatedDataSetId.equals(
                                                    blockingResultInfo.getResultId()))
                            .mapToLong(BlockingResultInfo::getNumBytesProduced)
                            .sum();
            aggregatedInputBytesByTypeNumber(
                    adaptiveJoinNode, upstreamEdge.getTypeNumber(), producedBytes);
        }

        FlinkJoinType joinType = adaptiveJoin.getJoinType();
        Long leftInputSize = null;
        Long rightInputSize = null;

        // When either input side of the adaptive join meets broadcast requirements, the broadcast
        // optimization can be immediately applied. This allows the opposite side to produce data
        // in a pointwise manner if it has not yet started scheduling, thereby reducing the costs
        // associated with shuffle writes and network overhead. Furthermore, in the future,
        // when multi-input support is available in the runtime, it could enable chaining large
        // input nodes with adaptive join nodes, further minimizing overall overhead.
        if (context.checkUpstreamNodesFinished(adaptiveJoinNode, LEFT_INPUT_TYPE_NUMBER)) {
            leftInputSize =
                    aggregatedInputBytesByTypeNumberAndNodeId
                            .get(adaptiveJoinNode.getId())
                            .get(LEFT_INPUT_TYPE_NUMBER);
            checkState(
                    leftInputSize != null,
                    "Left input bytes of adaptive join [%s] is unknown, which is unexpected.",
                    adaptiveJoinNode.getId());
            boolean leftIsBuild = true;
            if (checkInputSideCanBeBroadcast(joinType, leftIsBuild, leftInputSize)
                    && tryBroadcastOptimization(
                            adaptiveJoinNode, context, adaptiveJoin, leftIsBuild, leftInputSize)) {
                return;
            }
        }
        if (context.checkUpstreamNodesFinished(adaptiveJoinNode, RIGHT_INPUT_TYPE_NUMBER)) {
            rightInputSize =
                    aggregatedInputBytesByTypeNumberAndNodeId
                            .get(adaptiveJoinNode.getId())
                            .get(RIGHT_INPUT_TYPE_NUMBER);
            checkState(
                    rightInputSize != null,
                    "Right input bytes of adaptive join [%s] is unknown, which is unexpected.",
                    adaptiveJoinNode.getId());
            boolean leftIsBuild = false;
            if (checkInputSideCanBeBroadcast(joinType, leftIsBuild, rightInputSize)
                    && tryBroadcastOptimization(
                            adaptiveJoinNode, context, adaptiveJoin, leftIsBuild, rightInputSize)) {
                return;
            }
        }

        // When neither input meets broadcast thresholds, recompute the smaller side to provide
        // better performance for the shuffle join.
        if (leftInputSize != null && rightInputSize != null) {
            LOG.debug(
                    "The size of the specified side of the input data for the join node [{}] "
                            + "is too large to be converted into a broadcast hash join. "
                            + "The Join type: {}, Broadcast threshold: {} bytes, Left input size: "
                            + "{} bytes, Right input size: {} bytes.",
                    adaptiveJoinNode.getId(),
                    joinType,
                    broadcastThreshold,
                    leftInputSize,
                    rightInputSize);
            boolean leftSmallerThanRight = leftInputSize < rightInputSize;
            adaptiveJoin.markAsBroadcastJoin(false, leftSmallerThanRight);
            optimizedAdaptiveJoinNodes.add(adaptiveJoinNode.getId());
            aggregatedInputBytesByTypeNumberAndNodeId.remove(adaptiveJoinNode.getId());
        }
    }

static ValueSetter createValueSetter(LogicalType elementType) {
        // ordered by type root definition
        switch (elementType.getTypeRoot()) {
            case CHAR:
            case VARCHAR:
                return (writer, pos, value) -> writer.writeString(pos, (StringData) value);
            case BOOLEAN:
                return (writer, pos, value) -> writer.writeBoolean(pos, (boolean) value);
            case BINARY:
            case VARBINARY:
            case UUID:
                return (writer, pos, value) -> writer.writeBinary(pos, (byte[]) value);
            case DECIMAL:
                final int decimalPrecision = getPrecision(elementType);
                return (writer, pos, value) ->
                        writer.writeDecimal(pos, (DecimalData) value, decimalPrecision);
            case TINYINT:
                return (writer, pos, value) -> writer.writeByte(pos, (byte) value);
            case SMALLINT:
                return (writer, pos, value) -> writer.writeShort(pos, (short) value);
            case INTEGER:
            case DATE:
            case TIME_WITHOUT_TIME_ZONE:
            case INTERVAL_YEAR_MONTH:
                return (writer, pos, value) -> writer.writeInt(pos, (int) value);
            case BIGINT:
            case INTERVAL_DAY_TIME:
                return (writer, pos, value) -> writer.writeLong(pos, (long) value);
            case FLOAT:
                return (writer, pos, value) -> writer.writeFloat(pos, (float) value);
            case DOUBLE:
                return (writer, pos, value) -> writer.writeDouble(pos, (double) value);
            case TIMESTAMP_WITHOUT_TIME_ZONE:
            case TIMESTAMP_WITH_LOCAL_TIME_ZONE:
                final int timestampPrecision = getPrecision(elementType);
                return (writer, pos, value) ->
                        writer.writeTimestamp(pos, (TimestampData) value, timestampPrecision);
            case TIMESTAMP_WITH_TIME_ZONE:
                throw new UnsupportedOperationException();
            case ARRAY:
                final TypeSerializer<ArrayData> arraySerializer =
                        InternalSerializers.create(elementType);
                return (writer, pos, value) ->
                        writer.writeArray(
                                pos, (ArrayData) value, (ArrayDataSerializer) arraySerializer);
            case MULTISET:
            case MAP:
                final TypeSerializer<MapData> mapSerializer =
                        InternalSerializers.create(elementType);
                return (writer, pos, value) ->
                        writer.writeMap(pos, (MapData) value, (MapDataSerializer) mapSerializer);
            case ROW:
            case STRUCTURED_TYPE:
                final TypeSerializer<RowData> rowSerializer =
                        InternalSerializers.create(elementType);
                return (writer, pos, value) ->
                        writer.writeRow(pos, (RowData) value, (RowDataSerializer) rowSerializer);
            case DISTINCT_TYPE:
                return createValueSetter(((DistinctType) elementType).getSourceType());
            case RAW:
                final TypeSerializer<?> rawSerializer = InternalSerializers.create(elementType);
                return (writer, pos, value) ->
                        writer.writeRawValue(
                                pos,
                                (RawValueData<?>) value,
                                (RawValueDataSerializer<?>) rawSerializer);
            case VARIANT:
                return (writer, pos, value) -> writer.writeVariant(pos, (Variant) value);
            case BITMAP:
                return (writer, pos, value) -> writer.writeBitmap(pos, (Bitmap) value);
            case NULL:
            case SYMBOL:
            case UNRESOLVED:
            case DESCRIPTOR:
            default:
                throw new IllegalArgumentException();
        }
    }

static ContainerLaunchContext createTaskExecutorContext(
            org.apache.flink.configuration.Configuration flinkConfig,
            YarnConfiguration yarnConfig,
            YarnResourceManagerDriverConfiguration configuration,
            ContaineredTaskManagerParameters tmParams,
            String taskManagerDynamicProperties,
            String workingDirectory,
            Class<?> taskManagerMainClass,
            Logger log)
            throws Exception {

        // get and validate all relevant variables

        String remoteFlinkJarPath =
                checkNotNull(
                        configuration.getFlinkDistJar(),
                        "Environment variable %s not set",
                        YarnConfigKeys.FLINK_DIST_JAR);

        String shipListString =
                checkNotNull(
                        configuration.getClientShipFiles(),
                        "Environment variable %s not set",
                        YarnConfigKeys.ENV_CLIENT_SHIP_FILES);

        final String remoteKeytabPath = configuration.getRemoteKeytabPath();
        final String localKeytabPath = configuration.getLocalKeytabPath();
        final String keytabPrincipal = configuration.getKeytabPrinciple();
        final String remoteYarnConfPath = configuration.getYarnSiteXMLPath();
        final String remoteKrb5Path = configuration.getKrb5Path();

        if (log.isDebugEnabled()) {
            log.debug("TM:remote keytab path obtained {}", remoteKeytabPath);
            log.debug("TM:local keytab path obtained {}", localKeytabPath);
            log.debug("TM:keytab principal obtained {}", keytabPrincipal);
            log.debug("TM:remote yarn conf path obtained {}", remoteYarnConfPath);
            log.debug("TM:remote krb5 path obtained {}", remoteKrb5Path);
        }

        String classPathString =
                checkNotNull(
                        configuration.getFlinkClasspath(),
                        "Environment variable %s not set",
                        YarnConfigKeys.ENV_FLINK_CLASSPATH);

        // register keytab
        LocalResource keytabResource = null;
        if (remoteKeytabPath != null) {
            log.info(
                    "TM:Adding keytab {} to the container local resource bucket", remoteKeytabPath);
            Path keytabPath = new Path(remoteKeytabPath);
            FileSystem fs = keytabPath.getFileSystem(yarnConfig);
            keytabResource = registerLocalResource(fs, keytabPath, LocalResourceType.FILE);
        }

        // To support Yarn Secure Integration Test Scenario
        LocalResource yarnConfResource = null;
        if (remoteYarnConfPath != null) {
            log.info(
                    "TM:Adding remoteYarnConfPath {} to the container local resource bucket",
                    remoteYarnConfPath);
            Path yarnConfPath = new Path(remoteYarnConfPath);
            FileSystem fs = yarnConfPath.getFileSystem(yarnConfig);
            yarnConfResource = registerLocalResource(fs, yarnConfPath, LocalResourceType.FILE);
        }

        // register krb5.conf
        LocalResource krb5ConfResource = null;
        boolean hasKrb5 = false;
        if (remoteKrb5Path != null) {
            log.info(
                    "Adding remoteKrb5Path {} to the container local resource bucket",
                    remoteKrb5Path);
            Path krb5ConfPath = new Path(remoteKrb5Path);
            FileSystem fs = krb5ConfPath.getFileSystem(yarnConfig);
            krb5ConfResource = registerLocalResource(fs, krb5ConfPath, LocalResourceType.FILE);
            hasKrb5 = true;
        }

        Map<String, LocalResource> taskManagerLocalResources = new HashMap<>();

        // register Flink Jar with remote HDFS
        final YarnLocalResourceDescriptor flinkDistLocalResourceDesc =
                YarnLocalResourceDescriptor.fromString(remoteFlinkJarPath);
        taskManagerLocalResources.put(
                flinkDistLocalResourceDesc.getResourceKey(),
                flinkDistLocalResourceDesc.toLocalResource());

        // To support Yarn Secure Integration Test Scenario
        if (yarnConfResource != null) {
            taskManagerLocalResources.put(YARN_SITE_FILE_NAME, yarnConfResource);
        }
        if (krb5ConfResource != null) {
            taskManagerLocalResources.put(KRB5_FILE_NAME, krb5ConfResource);
        }
        if (keytabResource != null) {
            taskManagerLocalResources.put(localKeytabPath, keytabResource);
        }

        // prepare additional files to be shipped
        decodeYarnLocalResourceDescriptorListFromString(shipListString)
                .forEach(
                        resourceDesc ->
                                taskManagerLocalResources.put(
                                        resourceDesc.getResourceKey(),
                                        resourceDesc.toLocalResource()));

        // now that all resources are prepared, we can create the launch context

        log.info("Creating container launch context for TaskManagers");

        boolean hasLogback = new File(workingDirectory, "logback.xml").exists();
        boolean hasLog4j = new File(workingDirectory, "log4j.properties").exists();

        String launchCommand =
                getTaskManagerShellCommand(
                        flinkConfig,
                        tmParams,
                        ".",
                        ApplicationConstants.LOG_DIR_EXPANSION_VAR,
                        hasLogback,
                        hasLog4j,
                        hasKrb5,
                        taskManagerMainClass,
                        taskManagerDynamicProperties);

        if (log.isDebugEnabled()) {
            log.debug("Starting TaskManagers with command: " + launchCommand);
        } else {
            log.info("Starting TaskManagers");
        }

        ContainerLaunchContext ctx = Records.newRecord(ContainerLaunchContext.class);
        ctx.setCommands(Collections.singletonList(launchCommand));
        ctx.setLocalResources(taskManagerLocalResources);

        Map<String, String> containerEnv = new HashMap<>();
        containerEnv.putAll(tmParams.taskManagerEnv());

        // add YARN classpath, etc to the container environment
        containerEnv.put(ENV_FLINK_CLASSPATH, classPathString);
        setupYarnClassPath(yarnConfig, containerEnv);

        containerEnv.put(
                YarnConfigKeys.ENV_HADOOP_USER_NAME,
                UserGroupInformation.getCurrentUser().getUserName());

        if (remoteKeytabPath != null && localKeytabPath != null && keytabPrincipal != null) {
            containerEnv.put(YarnConfigKeys.REMOTE_KEYTAB_PATH, remoteKeytabPath);
            containerEnv.put(YarnConfigKeys.LOCAL_KEYTAB_PATH, localKeytabPath);
            containerEnv.put(YarnConfigKeys.KEYTAB_PRINCIPAL, keytabPrincipal);
        } else if (localKeytabPath != null && keytabPrincipal != null) {
            containerEnv.put(YarnConfigKeys.LOCAL_KEYTAB_PATH, localKeytabPath);
            containerEnv.put(YarnConfigKeys.KEYTAB_PRINCIPAL, keytabPrincipal);
        }

        ctx.setEnvironment(containerEnv);

        setAclsFor(ctx, flinkConfig);

        // For TaskManager YARN container context, read the tokens from the jobmanager yarn
        // container local file.
        // NOTE: must read the tokens from the local file, not from the UGI context, because if UGI
        // is login
        // using Kerberos keytabs, there is no HDFS delegation token in the UGI context.
        final String fileLocation = System.getenv(UserGroupInformation.HADOOP_TOKEN_FILE_LOCATION);

        if (fileLocation != null) {
            log.debug("Adding security tokens to TaskExecutor's container launch context.");

            try (DataOutputBuffer dob = new DataOutputBuffer()) {
                Credentials cred =
                        Credentials.readTokenStorageFile(
                                new File(fileLocation),
                                HadoopUtils.getHadoopConfiguration(flinkConfig));

                // Filter out AMRMToken before setting the tokens to the TaskManager container
                // context.
                Credentials taskManagerCred = new Credentials();
                Collection<Token<? extends TokenIdentifier>> userTokens = cred.getAllTokens();
                for (Token<? extends TokenIdentifier> token : userTokens) {
                    if (!token.getKind().equals(AMRMTokenIdentifier.KIND_NAME)) {
                        taskManagerCred.addToken(token.getService(), token);
                    }
                }

                taskManagerCred.writeTokenStorageToStream(dob);
                ByteBuffer securityTokens = ByteBuffer.wrap(dob.getData(), 0, dob.getLength());
                ctx.setTokens(securityTokens);
            } catch (Throwable t) {
                log.error("Failed to add Hadoop's security tokens.", t);
            }
        } else {
            log.info(
                    "Could not set security tokens because Hadoop's token file location is unknown.");
        }

        return ctx;
    }

List<String> registerMultipleLocalResources(
            final Collection<Path> shipFiles,
            final String localResourcesDirectory,
            final LocalResourceType resourceType)
            throws IOException {

        final List<Path> localPaths = new ArrayList<>();
        final List<Path> relativePaths = new ArrayList<>();
        for (Path shipFile : shipFiles) {
            if (Utils.isRemotePath(shipFile.toString())) {
                if (fileSystem.isDirectory(shipFile)) {
                    final URI parentURI = shipFile.getParent().toUri();
                    final RemoteIterator<LocatedFileStatus> iterable =
                            fileSystem.listFiles(shipFile, true);
                    while (iterable.hasNext()) {
                        final Path current = iterable.next().getPath();
                        localPaths.add(current);
                        relativePaths.add(
                                new Path(
                                        localResourcesDirectory,
                                        parentURI.relativize(current.toUri()).getPath()));
                    }
                    continue;
                }
            } else {
                final File file = new File(shipFile.toUri().getPath());
                if (file.isDirectory()) {
                    final java.nio.file.Path shipPath = file.toPath().toRealPath();
                    final java.nio.file.Path parentPath = shipPath.getParent();
                    Collection<java.nio.file.Path> paths =
                            FileUtils.listFilesInDirectory(shipPath, path -> true);
                    for (java.nio.file.Path javaPath : paths) {
                        localPaths.add(new Path(javaPath.toUri()));
                        relativePaths.add(
                                new Path(
                                        localResourcesDirectory,
                                        parentPath.relativize(javaPath).toString()));
                    }
                    continue;
                }
            }
            localPaths.add(shipFile);
            relativePaths.add(new Path(localResourcesDirectory, shipFile.getName()));
        }

        final Set<String> archives = new HashSet<>();
        final Set<String> resources = new HashSet<>();
        for (int i = 0; i < localPaths.size(); i++) {
            final Path localPath = localPaths.get(i);
            final Path relativePath = relativePaths.get(i);
            if (!isFlinkDistJar(relativePath.getName())) {
                final String key = relativePath.toString();
                final YarnLocalResourceDescriptor resourceDescriptor =
                        registerSingleLocalResource(
                                key,
                                localPath,
                                relativePath.getParent().toString(),
                                resourceType,
                                true,
                                true);

                if (!resourceDescriptor.alreadyRegisteredAsLocalResource()) {
                    if (key.endsWith("jar")) {
                        archives.add(relativePath.toString());
                    } else {
                        resources.add(relativePath.getParent().toString());
                    }
                }
            }
        }

        // construct classpath, we always want resource directories to go first, we also sort
        // both resources and archives in order to make classpath deterministic
        final ArrayList<String> classPaths = new ArrayList<>();
        resources.stream().sorted().forEach(classPaths::add);
        archives.stream().sorted().forEach(classPaths::add);
        return classPaths;
    }

@Override
    public Configuration toConfiguration(CommandLine commandLine) throws FlinkException {
        // we ignore the addressOption because it can only contain "yarn-cluster"
        final Configuration effectiveConfiguration = new Configuration();

        applyDescriptorOptionToConfig(commandLine, effectiveConfiguration);

        final ApplicationId applicationId = getApplicationId(commandLine);
        if (applicationId != null) {
            final String zooKeeperNamespace;
            if (commandLine.hasOption(zookeeperNamespace.getOpt())) {
                zooKeeperNamespace = commandLine.getOptionValue(zookeeperNamespace.getOpt());
            } else {
                zooKeeperNamespace =
                        effectiveConfiguration.get(HA_CLUSTER_ID, applicationId.toString());
            }

            effectiveConfiguration.set(HA_CLUSTER_ID, zooKeeperNamespace);
            effectiveConfiguration.set(YarnConfigOptions.APPLICATION_ID, applicationId.toString());
        }
        effectiveConfiguration.set(DeploymentOptions.TARGET, YarnSessionClusterExecutor.NAME);

        if (commandLine.hasOption(jmMemory.getOpt())) {
            String jmMemoryVal = commandLine.getOptionValue(jmMemory.getOpt());
            if (!MemorySize.MemoryUnit.hasUnit(jmMemoryVal)) {
                jmMemoryVal += "m";
            }
            effectiveConfiguration.set(
                    JobManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse(jmMemoryVal));
        }

        if (commandLine.hasOption(tmMemory.getOpt())) {
            String tmMemoryVal = commandLine.getOptionValue(tmMemory.getOpt());
            if (!MemorySize.MemoryUnit.hasUnit(tmMemoryVal)) {
                tmMemoryVal += "m";
            }
            effectiveConfiguration.set(
                    TaskManagerOptions.TOTAL_PROCESS_MEMORY, MemorySize.parse(tmMemoryVal));
        }

        if (commandLine.hasOption(slots.getOpt())) {
            effectiveConfiguration.set(
                    TaskManagerOptions.NUM_TASK_SLOTS,
                    Integer.parseInt(commandLine.getOptionValue(slots.getOpt())));
        }

        dynamicPropertiesEncoded = encodeDynamicProperties(commandLine);
        if (!dynamicPropertiesEncoded.isEmpty()) {
            Map<String, String> dynProperties = getDynamicProperties(dynamicPropertiesEncoded);
            for (Map.Entry<String, String> dynProperty : dynProperties.entrySet()) {
                effectiveConfiguration.setString(dynProperty.getKey(), dynProperty.getValue());
            }
        }

        if (isYarnPropertiesFileMode(commandLine)) {
            return applyYarnProperties(effectiveConfiguration);
        } else {
            return effectiveConfiguration;
        }
    }

